window.TADABBUR_SAD = {"_meta":{"description":"تدبّر سورة ص (٣٨) — سورةٌ مكّيّةٌ محورُها إثباتُ التوحيدِ والرسالة، وتسليةُ النبيِّ ﷺ بقصصِ الأنبياءِ الصابرين، والتذكيرُ بالبعثِ والجزاء. تفتتح بالقسمِ بالقرآنِ ذي الذكر، وتعجُّبِ المشركين من دعوةِ التوحيد، ثم قصصُ داودَ وخصومتِه وتوبتِه، وسليمانَ وفتنتِه وأوبتِه، وأيوبَ وصبرِه، وذكرُ إبراهيمَ وإسحاقَ ويعقوبَ وإسماعيلَ واليسعَ وذي الكفل، ثم مشهدُ الجنّةِ لأهلها والنارِ لأهلها، وخصومةُ أهلِ النار، وقصةُ آدمَ وإباءِ إبليسَ وطردِه واستنظارِه، وختامُ السورةِ بأنّ القرآنَ ذكرٌ للعالمين.","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":38,"name":"ص","total_ayahs":88,"audio":[1,17,26,29,44,50,65,71,76,87],"passages":[{"title":"القسمُ بالقرآنِ، وكِبرُ الكافرين وعجبُهم من التوحيد، وعجزُهم عن معارضةِ الله","range":[1,11],"theme":"القسمُ بالقرآنِ ذي الذكر، وأنّ سببَ كفرِ الكافرين الكِبرُ والشقاقُ لا خفاءُ الحق، والتخويفُ بهلاكِ القرونِ الماضيةِ حين لا مناص، وعجبُهم من دعوةِ التوحيدِ وتواصيهم على الثباتِ على آلهتهم، واعتراضُهم على اختصاصِ النبيِّ بالوحيِ حسدًا، وبيانُ أنّ خزائنَ الرحمةِ ومُلكَ السماواتِ بيدِ الله وحده، وأنهم جندٌ مهزوم","verses":[{"n":1,"reflection":{"text":"«ص والقرآن ذي الذكر» — أقسم الله بالقرآنِ ذي الذكرِ والشرفِ والتذكيرِ على صدقِ الرسالة؛ ففي هذا تعظيمُ شأنِ القرآنِ وأنه ذكرٌ وشرف؛ فعظّم القرآنَ في قلبك، واجعله ذكرك وشرفك، فالقرآنُ ذكرٌ لمن تذكّر به، وشرفٌ لمن تمسّك به، فاعتنِ به تلاوةً وتدبّرًا وعملًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ واتّخاذُه ذكرًا وشرفًا."},"action":{"text":"عظّم القرآنَ في قلبك، فقد أقسم الله به ووصفه بأنه «ذو الذكر» أي ذو الشرفِ والتذكير «ص والقرآن ذي الذكر»؛ فالقرآنُ ذكرٌ يذكّرك بربك وبالآخرةِ وبما ينفعك، وشرفٌ لك ولأمّتك؛ فاجعله ذكرك في يومك: اتلُه بتدبّر، وتذكّر به عند الغفلة، وتشرّف بحمله والعملِ به؛ فمن اعتنى بالقرآنِ رفعه الله، ومن أعرض عنه وضعه؛ فاجعل لك وردًا يوميًّا من تلاوته وتدبّره؛ فالقرآنُ حبلُ الله المتين، والذكرُ الحكيم؛ فتشرّف بصحبته، واستكثر من ذكرِ الله به؛ فبه تحيا القلوب، وتُنال السعادةُ في الدارين."}},{"n":2,"reflection":{"text":"«بل الذين كفروا في عزة وشقاق» — بل الذين كفروا في تكبّرٍ عن الحقِّ وحميّةٍ جاهليةٍ ومخالفةٍ وعداوةٍ للنبيّ؛ ففي هذا بيانُ أنّ سببَ كفرهم الكِبرُ لا خفاءُ الحق؛ فاحذر الكِبرَ عن قبولِ الحقّ، فإنه أصلُ الكفرِ والصدود، فتواضع للحقِّ واقبله ممّن جاء به، فالكِبرُ يمنع من الهداية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ عن قبولِ الحقّ، فهو أصلُ الصدود."},"action":{"text":"احذر الكِبرَ عن قبولِ الحقّ، فإنّ الله بيّن أنّ سببَ كفرِ الكافرين ليس خفاءَ الحقِّ ولا ضعفَ الحجّة، بل الكِبرُ والحميّةُ والمخالفةُ والعداوة «بل الذين كفروا في عزة وشقاق»؛ فما منعهم من الإيمانِ إلا استكبارهم عن الحقِّ وشقاقهم للنبيّ؛ فالكِبرُ أعظمُ حاجبٍ عن الهداية؛ فتواضع للحقِّ، واقبله ممّن جاء به ولو كان صغيرًا أو دونك؛ فالكِبرُ بطرُ الحقِّ وغمطُ الناس؛ فلا يدخل الجنّةَ من كان في قلبه مثقالُ ذرّةٍ من كبر؛ فطهّر قلبك من الكِبرِ والعناد؛ واقبل الحقَّ بانقيادٍ وتواضع؛ فمن تواضع للحقِّ رفعه الله وهداه، ومن استكبر عنه أضلّه الله وأرداه؛ فاجعل قلبك منقادًا للحقِّ، خاضعًا له، لا مستكبرًا معاندًا."}},{"n":3,"reflection":{"text":"«كم أهلكنا من قبلهم من قرن فنادوا ولات حين مناص» — كثيرٌ من الأممِ أهلكناهم قبل هؤلاء، فنادوا واستغاثوا حين نزل العذابُ، ولا وقتَ نجاةٍ ولا مهرب؛ ففي هذا التخويفُ بعاقبةِ المكذّبين وأنّ التوبةَ لا تنفع عند العذاب؛ فبادر بالتوبةِ في وقتها، فلا تنفع التوبةُ حين نزولِ العذاب، فاغتنم مهلةَ الحياةِ قبل فواتِ الأوان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ قبل نزولِ العذاب، فلا مناصَ حينئذ."},"action":{"text":"اعتبر بعاقبةِ الأممِ الكثيرةِ التي أهلكها الله قبل هؤلاء المكذّبين، فلمّا نزل بهم العذابُ نادوا واستغاثوا وتابوا، ولكن لا وقتَ نجاةٍ ولا مهربٍ ولا فوت «كم أهلكنا من قبلهم من قرن فنادوا ولات حين مناص»؛ فالتوبةُ لا تنفع عند معاينةِ العذاب؛ فبادر بالتوبةِ في وقتها المقبول، قبل أن ينزل بك العذابُ أو يحضرك الموت؛ فاغتنم مهلةَ الحياةِ والصحّةِ للتوبةِ والعمل؛ فمن سوّف بالتوبةِ حتى نزل العذابُ لم تنفعه؛ فلا تؤخّر التوبةَ، فإنّ الأجلَ قد يأتي بغتة؛ فتب إلى الله الآن، واعمل صالحًا قبل فواتِ الأوان؛ فالسعيدُ من بادر بالتوبةِ في زمنِ الإمهال؛ فباب التوبةِ مفتوحٌ ما لم تبلغ الروحُ الحلقوم أو تطلع الشمسُ من مغربها؛ فبادر قبل أن تقول: يا ليتني قدّمت لحياتي."}},{"n":4,"reflection":{"text":"«وعجبوا أن جاءهم منذر منهم وقال الكافرون هذا ساحر كذاب» — وتعجّب المشركون أن جاءهم رسولٌ منذِرٌ من جنسهم يعرفونه، ووصفوه بالسحرِ والكذب؛ ففي هذا بيانُ عنادهم ورميهم الحقَّ بالباطل؛ فاحذر أن تردّ الحقَّ بالتهمِ الباطلة، بل تأمّل الحقَّ بإنصاف، فردُّ الحقِّ بالسبِّ والتهمةِ من صفاتِ المعاندين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ الحقِّ بإنصاف، وتركُ ردِّه بالتهمِ الباطلة."},"action":{"text":"اعلم أنّ المشركين تعجّبوا أن يأتيهم رسولٌ منذِرٌ بشرٌ من جنسهم يعرفون نسبه وصدقه، فبادروا إلى ردِّ دعوته برميِه بالسحرِ والكذب «وعجبوا أن جاءهم منذر منهم وقال الكافرون هذا ساحر كذاب»؛ فهذا دأبُ المعاندين: ردُّ الحقِّ بالتهمِ والسبِّ لا بالحجّةِ والدليل؛ فاحذر أن تردّ الحقَّ إذا جاءك برميِ صاحبه بالتهمِ الباطلة؛ بل تأمّل الحقَّ بإنصافٍ وتجرّد، وانظر في الحجّةِ والدليل؛ فمن ردّ الحقَّ بالتهمةِ والشتمِ فقد أعرض عن الإنصاف؛ فاجعل ميزانك في قبولِ القولِ ودفعه: الحجّةَ والبرهانَ، لا الهوى والتشهير؛ فكم من حقٍّ رُدّ بتهمةٍ باطلة؛ فلا تكن ممّن يقابل الناصحَ بالاتّهام؛ بل اقبل النصحَ والحقَّ ممّن جاء به؛ فالإنصافُ عزيز، وأهله قليل؛ فكن من المنصفين الذين يزنون الأقوالَ بميزانِ الحقّ."}},{"n":5,"reflection":{"text":"«أجعل الآلهة إلها واحدا إن هذا لشيء عجاب» — أاختصر الآلهةَ الكثيرةَ في إلهٍ واحد؟ إنّ هذا لشيءٌ عجيبٌ مستنكَر (في زعمهم)؛ ففي هذا استعظامهم التوحيدَ الذي هو أعظمُ الحقّ؛ فتأمّل انقلابَ الموازين عند أهلِ الباطل: يستعظمون الحقَّ ويستنكرونه، فاحذر أن ينقلب ميزانك، واعلم أنّ التوحيدَ أعظمُ الحقِّ وأبينُه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ التوحيدِ وإدراكُ أنه أعظمُ الحقّ، لا العجب."},"action":{"text":"تأمّل كيف استعظم المشركون دعوةَ التوحيدِ واستنكروها، فقالوا متعجّبين: أاختصر الآلهةَ الكثيرةَ في إلهٍ واحد؟ إنّ هذا لشيءٌ عجيبٌ منكَر «أجعل الآلهة إلها واحدا إن هذا لشيء عجاب»؛ فانظر إلى انقلابِ الموازينِ عند أهلِ الباطل: يستعظمون أعظمَ الحقِّ وأبينَه — وهو توحيدُ الله — ويألفون أبطلَ الباطلِ وهو عبادةُ الأصنام؛ فاحذر أن ينقلب ميزانك فتستنكر الحقَّ وتألف الباطل؛ واعلم أنّ التوحيدَ أعظمُ الحقِّ وأوضحه، وأنّ الشركَ أعظمُ الباطلِ وأقبحه؛ فالعقلُ السليمُ والفطرةُ المستقيمةُ تشهد أنّ الإلهَ واحد؛ فكيف يُستعجَب من عبادةِ إلهٍ واحدٍ خالقٍ رازق، ولا يُستعجَب من عبادةِ آلهةٍ عاجزةٍ لا تنفع ولا تضرّ؟ فعظّم التوحيدَ في قلبك، وأنكِر الشركَ واستقبحه؛ فالتوحيدُ حقٌّ بيّن، والشركُ باطلٌ عجيب؛ فاجعل ميزانك ميزانَ الفطرةِ والعقلِ والوحي."}},{"n":6,"reflection":{"text":"«وانطلق الملأ منهم أن امشوا واصبروا على آلهتكم إن هذا لشيء يراد» — وانطلق أشرافُ المشركين يحرّض بعضهم بعضًا: امضوا واثبتوا على عبادةِ آلهتكم، إنّ هذا الأمرَ (دعوةَ التوحيد) يُرادُ بنا لغرض؛ ففي هذا تحريضُهم على الباطلِ وتواصيهم به؛ فاحذر التواصيَ على الباطلِ والثباتِ عليه، بل تواصَ مع إخوانك على الحقِّ والصبرِ عليه، فالتواصي بالحقِّ من صفاتِ الناجين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواصي بالحقِّ والصبرِ عليه، لا على الباطل."},"action":{"text":"تأمّل كيف انطلق أشرافُ المشركين يحرّض بعضهم بعضًا على الثباتِ على الباطل: امضوا واصبروا على عبادةِ آلهتكم ولا تستجيبوا لدعوةِ التوحيد، إنّ هذا أمرٌ يُرادُ بنا «وانطلق الملأ منهم أن امشوا واصبروا على آلهتكم إن هذا لشيء يراد»؛ فتواصوا على الباطلِ والصبرِ عليه؛ فاحذر التواصيَ على الباطلِ والتحريضِ عليه والثباتِ فيه؛ بل تواصَ مع إخوانك على الحقِّ والصبرِ عليه؛ فالتواصي بالحقِّ والتواصي بالصبرِ من صفاتِ الناجين من الخسران؛ فكما يتواصى أهلُ الباطلِ على باطلهم، فتواصَ أنت وإخوانك على الحقِّ وطاعةِ الله والصبرِ عليها؛ فأعِن إخوانك على الخير، وثبّتهم على الحقّ؛ فالمؤمنُ للمؤمنِ كالبنيانِ يشدّ بعضه بعضًا؛ فاجعل صحبتك ومجالسك على التعاونِ على البرِّ والتقوى، والتواصي بالحقِّ والصبر؛ فالثباتُ على الحقِّ يقوى بالتواصي والتعاون."}},{"n":7,"reflection":{"text":"«ما سمعنا بهذا في الملة الآخرة إن هذا إلا اختلاق» — ما سمعنا بهذا التوحيدِ في دينِ آبائنا القريبِ أو النصرانية، ما هذا إلا كذبٌ مفترى؛ ففي هذا احتجاجهم بالتقليدِ وردُّ الحقِّ بعدمِ الإلفِ به؛ فاحذر ردَّ الحقِّ لمجرّدِ أنك لم تألفه أو خالف ما عليه الناس، بل زِن الحقَّ بدليله لا بألفةِ الناسِ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"وزنُ الحقِّ بدليله لا بألفةِ الناسِ له أو تقليدهم."},"action":{"text":"اعلم أنّ المشركين ردّوا دعوةَ التوحيدِ بحجّةٍ باطلة: أنهم لم يسمعوا به في دينِ آبائهم القريبِ ولا في الملةِ الأخيرة، وزعموا أنه كذبٌ مفترى «ما سمعنا بهذا في الملة الآخرة إن هذا إلا اختلاق»؛ فردّوا الحقَّ لمجرّدِ أنهم لم يألفوه ولم يسمعوا به من آبائهم؛ فاحذر ردَّ الحقِّ لمجرّدِ أنك لم تألفه، أو أنه خالف ما عليه أكثرُ الناسِ وآباؤك؛ فليست الغرابةُ وعدمُ الإلفِ دليلًا على البطلان؛ بل زِن الحقَّ بدليله وبرهانه، لا بألفةِ الناسِ له أو تقليدهم لآبائهم؛ فكم من حقٍّ ردّه الناسُ لأنهم لم يألفوه؛ فلا تجعل عادةَ الناسِ وتقليدَ الآباءِ ميزانًا للحقِّ والباطل؛ بل اجعل الميزانَ الوحيَ والدليلَ والعقلَ الصريح؛ فمن ردّ الحقَّ لأنه غريبٌ عليه فقد اتّبع هواه؛ فاقبل الحقَّ ولو كان غريبًا، ما دام الدليلُ يشهد له؛ فالحقُّ لا يُعرَف بألفةِ الناسِ ولا بكثرتهم، بل بدليله."}},{"n":8,"reflection":{"text":"«أأنزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب» — أخُصَّ محمدٌ بالقرآنِ من بيننا؟ بل هم في شكٍّ من الوحي، بل لم يذوقوا عذابي بعدُ فيؤمنوا؛ ففي هذا حسدهم واعتراضهم على اختيارِ الله لرسوله؛ فاحذر الاعتراضَ على قسمةِ الله وفضلِه، فالله أعلمُ حيث يجعل رسالته وفضله، فسلّم لحكمةِ الله في اختياره واصطفائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمةِ الله في اختياره وفضلِه، وتركُ الاعتراض."},"action":{"text":"اعلم أنّ المشركين اعترضوا على اختيارِ الله لنبيّه محمدٍ ﷺ حسدًا: أخُصَّ بالقرآنِ والوحيِ من بيننا؟ فردّ الله عليهم بأنهم في شكٍّ من الوحيِ لم يتيقّنوه، وأنهم لم يذوقوا عذابه بعدُ فيؤمنوا مضطرّين «أأنزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب»؛ فاعترضوا على قسمةِ الله وفضلِه واصطفائه؛ فاحذر الاعتراضَ على قسمةِ الله وفضلِه وتدبيرِه؛ فالله أعلمُ حيث يجعل رسالته وفضله ونعمه؛ يختصّ برحمتِه من يشاء بحكمته؛ فسلّم لحكمةِ الله في اختياره واصطفائه وقسمتِه؛ ولا تعترض على تفضيلِ الله بعضَ خلقه على بعض؛ فالحسدُ والاعتراضُ على فضلِ الله من صفاتِ الكافرين؛ فارضَ بقسمةِ الله، واسأله من فضله، ولا تحسد الناسَ على ما آتاهم الله؛ فمن اعترض على قسمةِ الله فقد اعترض على حكمته؛ فسلّم وارضَ، واطلب فضلَ الله بالسؤالِ لا بالحسد."}},{"n":9,"reflection":{"text":"«أم عندهم خزائن رحمة ربك العزيز الوهاب» — أعندهم خزائنُ رحمةِ ربّك العزيزِ الغالبِ الوهّابِ كثيرِ العطاء، حتى يعطوا النبوّةَ من شاؤوا؟ ففي هذا بيانُ أنّ الفضلَ بيدِ الله وحده؛ فاعلم أنّ خزائنَ الفضلِ والرحمةِ بيدِ الله، فاطلبها منه وحده، ولا تحسد من آتاه الله فضله، فالوهّابُ يعطي من يشاء بحكمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الفضلِ من الله وحده، فخزائنُ رحمتِه بيده."},"action":{"text":"تأمّل ردَّ الله على المشركين المعترضين على النبوّة: أعندهم خزائنُ رحمةِ ربّك العزيزِ الغالبِ الوهّابِ كثيرِ العطاء، حتى يتحكّموا فيمن ينزل عليه الوحيُ والرسالة؟ «أم عندهم خزائن رحمة ربك العزيز الوهاب»؛ فخزائنُ الرحمةِ والفضلِ بيدِ الله وحده، يؤتيها من يشاء بحكمته؛ فاعلم أنّ الفضلَ كلَّه — النبوّةَ والعلمَ والرزقَ والولدَ وكلَّ نعمة — بيدِ الله، خزائنه لا تنفد؛ فاطلب الفضلَ والرحمةَ من الله وحده، فهو الوهّابُ العزيز؛ ولا تحسد من آتاه الله من فضله؛ فالله يعطي من يشاء بحكمته وعلمه؛ فألحّ على الله في طلبِ فضله ورحمته؛ فخزائنه ملأى لا تغيضها النفقة؛ فمن سأل الله من فضله أعطاه، ومن حسد الناسَ على فضلِ الله حُرِم؛ فاجعل رغبتك إلى الله الوهّاب؛ فهو العزيزُ الذي لا يُغالَب، الوهّابُ الذي لا ينفد عطاؤه؛ فاطلب من خزائنِ رحمتِه، وارضَ بقسمته، ولا تعترض على فضله."}},{"n":10,"reflection":{"text":"«أم لهم ملك السماوات والأرض وما بينهما فليرتقوا في الأسباب» — ألهم مُلكُ السماواتِ والأرضِ حتى يتصرّفوا في أمرِ النبوّةِ والرسالة؟ فإن زعموا ذلك فليصعدوا في الطرقِ الموصلةِ إلى السماءِ ليدبّروا الأمر؛ ففي هذا تعجيزهم وبيانُ أنّ المُلكَ والتدبيرَ لله وحده؛ فاعلم أنّ المُلكَ والتدبيرَ كلَّه لله، فسلّم لتدبيرِه، ولا تنازعه في أمره، فالأمرُ كلُّه بيده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لتدبيرِ الله، فالمُلكُ والأمرُ كلُّه بيده."},"action":{"text":"تأمّل تعجيزَ الله للمشركين المعترضين: ألهم مُلكُ السماواتِ والأرضِ وما بينهما، حتى يتحكّموا في أمرِ النبوّةِ والتدبير؟ فإن ادّعوا ذلك فليصعدوا في الأسبابِ والطرقِ الموصلةِ إلى السماءِ ليدبّروا الأمرَ ويمنعوا الوحيَ عمّن يشاؤون «أم لهم ملك السماوات والأرض وما بينهما فليرتقوا في الأسباب»؛ وهم عاجزون عن ذلك أشدَّ العجز؛ فالمُلكُ والتدبيرُ كلُّه لله وحده، لا يشاركه فيه أحد؛ فاعلم أنّ مُلكَ السماواتِ والأرضِ وتدبيرَ الأمرِ كلَّه بيدِ الله؛ فسلّم لتدبيرِ الله في خلقه، ولا تنازعه في أمره وحكمه؛ فمن أراد أن يدبّر مع الله أو يعترض على حكمه فقد جهل قدره وعجزه؛ فأنت وكلُّ الخلقِ عبيدٌ فقراءُ لا تملكون لأنفسكم نفعًا ولا ضرًّا؛ فكيف تنازعون مالكَ المُلكِ في تدبيره؟ فاخضع لله، وسلّم لأمره، وارضَ بحكمه؛ فالأمرُ كلُّه بيده، يدبّره بحكمته وعلمه؛ فما لك إلا التسليمُ والانقياد."}},{"n":11,"reflection":{"text":"«جند ما هنالك مهزوم من الأحزاب» — هؤلاء المشركون المتحزّبون على النبيِّ جندٌ حقيرٌ مهزومٌ لا محالة، كما هُزِمت الأحزابُ من قبلهم؛ ففي هذا بشارةٌ بهزيمةِ أعداءِ الحقِّ وتسليةٌ للنبيّ؛ فاعلم أنّ أعداءَ الحقِّ مهزومون ولو تحزّبوا وكثروا، فاثبت على الحقِّ ولا تخف كثرتهم، فالعاقبةُ للحقِّ وأهله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بهزيمةِ أعداءِ الحقِّ ولو تحزّبوا، والثباتُ عليه."},"action":{"text":"اعلم أنّ الله وصف المشركين المتحزّبين على النبيِّ ﷺ بأنهم جندٌ حقيرٌ مهزومٌ لا محالة، كما هُزِمت الأحزابُ المكذّبةُ من قبلهم «جند ما هنالك مهزوم من الأحزاب»؛ فهذه بشارةٌ بهزيمةِ أعداءِ الحقِّ وتسليةٌ للنبيِّ وأتباعه، وقد تحقّقت يومَ بدرٍ وغيره؛ فاعلم أنّ أعداءَ الحقِّ مهزومون مغلوبون ولو تحزّبوا وتكاثروا وأعدّوا؛ فالعاقبةُ للحقِّ وأهله؛ فاثبت على الحقِّ، ولا تخف كثرةَ المخالفين وتحزّبهم؛ فكم من فئةٍ قليلةٍ غلبت فئةً كثيرةً بإذنِ الله؛ فلا يهولنّك اجتماعُ أهلِ الباطلِ وكثرتهم؛ فإنّ نصرَ الله لأوليائه قريب، وهزيمةَ أعدائه محقّقة؛ فتوكّل على الله، واثبت على دينك، وابذل الأسباب؛ ثم ثق بوعدِ الله بنصرِ أوليائه وهزيمةِ أعدائه؛ فالباطلُ وإن انتفش وتحزّب فمصيره الزوالُ والهزيمة؛ فالعاقبةُ للمتّقين، والغلبةُ لجندِ الله."}}]},{"title":"تكذيبُ الأحزابِ السابقين ووعيدُهم، والأمرُ بالصبرِ وذكرِ داودَ الأوّاب","range":[12,20],"theme":"عدُّ الأممِ المكذّبةِ المهلَكة (قومِ نوحٍ وعادٍ وفرعونَ وثمودَ وقومِ لوطٍ وأصحابِ الأيكة) وأنّ تكذيبَ الرسلِ أوجب عقابهم، وأنّ المكذّبين ما ينتظرون إلا صيحةً واحدة، واستهزاؤهم باستعجالِ العذاب، والأمرُ للنبيِّ بالصبرِ وذكرِ داودَ ذي القوّةِ في العبادةِ الأوّابِ الذي سُخّرت معه الجبالُ والطيرُ تسبّح، وأوتي المُلكَ والحكمةَ وفصلَ الخطاب","verses":[{"n":12,"reflection":{"text":"«كذبت قبلهم قوم نوح وعاد وفرعون ذو الأوتاد» — كذّب قبل هؤلاء المشركين قومُ نوحٍ وعادٌ وفرعونُ صاحبُ الجنودِ والقوّةِ (ذو الأوتاد)؛ ففي هذا تسليةُ النبيِّ بأنّ التكذيبَ سنّةُ الأممِ الظالمة؛ فاعلم أنّ تكذيبَ الحقِّ قديم، فلا يحزنك تكذيبُ المكذّبين، واصبر كما صبر الرسلُ قبلك، فالتكذيبُ لا يضرّ الحقَّ ولا أهله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على التكذيب، وإدراكُ أنه سنّةُ الأممِ الظالمة."},"action":{"text":"اعلم أنّ التكذيبَ للرسلِ سنّةٌ قديمةٌ في الأممِ الظالمة، فقد كذّب قبل مشركي قريشٍ قومُ نوحٍ وعادٌ قومُ هودٍ وفرعونُ صاحبُ القوّةِ والجنودِ والبطشِ (ذو الأوتاد) «كذبت قبلهم قوم نوح وعاد وفرعون ذو الأوتاد»؛ ففي هذا تسليةٌ للنبيِّ ﷺ وأتباعه، وبيانٌ أنّ ما يلقونه من التكذيبِ ليس بدعًا؛ فاعلم أنّ تكذيبَ الحقِّ وأهله قديمٌ متكرّر؛ فلا يحزنك تكذيبُ المكذّبين وإعراضُ المعرضين؛ واصبر على أذاهم كما صبر الرسلُ من قبلك؛ فالتكذيبُ لا يضرّ الحقَّ ولا أهله، وإنما يضرّ المكذّبين أنفسهم؛ فتأسَّ بالرسلِ في الصبرِ على التكذيبِ والأذى؛ فما لقيت من تكذيبٍ فقد لقي الرسلُ أعظمَ منه فصبروا؛ فاصبر واحتسب، وامضِ في الحقِّ غيرَ مبالٍ بتكذيبِ المكذّبين؛ فالعاقبةُ لك، والهلاكُ لهم، كما كانت عاقبةُ من كذّب الرسلَ من قبل."}},{"n":13,"reflection":{"text":"«وثمود وقوم لوط وأصحاب الأيكة أولئك الأحزاب» — وكذّب ثمودُ قومُ صالح، وقومُ لوط، وأصحابُ الأيكةِ قومُ شعيب؛ أولئك هم الأحزابُ المكذّبةُ التي أُهلِكت؛ ففي هذا عدُّ الأممِ المهلَكةِ للعبرة؛ فاعتبر بمصارعِ الأممِ المكذّبة، واحذر أن تسلك سبيلهم، فمن كذّب الحقَّ أهلكه الله، فاتّبع الحقَّ لتنجو من مصيرهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأممِ المكذّبة، واتّباعُ الحقِّ للنجاة."},"action":{"text":"اعلم أنّ الله عدّ من الأحزابِ المكذّبةِ المهلَكة: ثمودَ قومَ صالح، وقومَ لوط، وأصحابَ الأيكةِ قومَ شعيب، مع من ذُكِر قبلهم؛ فقال: أولئك هم الأحزابُ الذين تحزّبوا على الحقِّ فأهلكهم الله «وثمود وقوم لوط وأصحاب الأيكة أولئك الأحزاب»؛ فاعتبر بمصارعِ هذه الأممِ المكذّبةِ التي أُهلِكت بتكذيبها؛ فكلٌّ منهم كذّب رسولَه فحقّ عليه العقاب؛ فاحذر أن تسلك سبيلهم في تكذيبِ الحقِّ والإعراضِ عنه؛ فمن كذّب الحقَّ وأصرّ عليه أهلكه الله كما أهلكهم؛ فاتّبع الحقَّ الذي جاءت به الرسلُ لتنجو من مصيرهم؛ فسِر في الأرضِ وانظر كيف كان عاقبةُ المكذّبين؛ فاجعل من مصارعهم عبرةً تحملك على الإيمانِ والاتّباع؛ فما هلكوا إلا بالتكذيبِ والعناد؛ فالنجاةُ في اتّباعِ الحقِّ والإيمانِ بالرسل، والهلاكُ في تكذيبهم والإعراضِ عنهم."}},{"n":14,"reflection":{"text":"«إن كل إلا كذب الرسل فحق عقاب» — ما كان كلُّ واحدٍ من تلك الأممِ إلا مكذّبًا للرسل، فوجب عليهم عقابي وحلّ بهم؛ ففي هذا أنّ تكذيبَ الرسلِ سببُ العقاب؛ فاحذر تكذيبَ رسلِ الله، فمن كذّبهم حقّ عليه العقاب، فآمن بالرسلِ جميعًا وصدّقهم، فتصديقُ الرسلِ سببُ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تكذيبِ الرسل، فهو سببُ العقاب، وتصديقُهم نجاة."},"action":{"text":"اعلم أنّ تلك الأممَ المهلَكةَ ما كان كلُّ واحدٍ منها إلا مكذّبًا لرسلِ الله، فوجب عليهم عقابُ الله وحلّ بهم جزاءَ تكذيبهم «إن كل إلا كذب الرسل فحق عقاب»؛ فتكذيبُ الرسلِ هو السببُ الجامعُ لهلاكهم وعقابهم؛ فاحذر تكذيبَ رسلِ الله أو الإعراضَ عمّا جاؤوا به؛ فمن كذّب الرسلَ أو رسولًا منهم حقّ عليه العقاب؛ فآمن بالرسلِ جميعًا وصدّقهم فيما بلّغوا؛ واعمل بما جاؤوا به من الحقّ؛ فتصديقُ الرسلِ والعملُ بما جاؤوا به سببُ النجاةِ والفوز؛ فلا تكن ممّن يكذّب الحقَّ فيحقّ عليه العقاب؛ بل كن من المصدّقين المتّبعين؛ فالرسلُ جاؤوا بالهدى ودينِ الحق؛ فمن اتّبعهم نجا وسعد، ومن كذّبهم هلك وشقي؛ فاجعل الإيمانَ بالرسلِ وتصديقهم واتّباعهم منهجَ حياتك؛ فبذلك تأمن العقابَ وتنال الثواب."}},{"n":15,"reflection":{"text":"«وما ينظر هؤلاء إلا صيحة واحدة ما لها من فواق» — وما ينتظر هؤلاء المكذّبون إلا صيحةً واحدةً (نفخةَ الصور) لا رجوعَ لها ولا مهلة؛ ففي هذا قربُ الأجلِ وسرعةُ مجيءِ الساعة؛ فاستعدّ للقاءِ الله، فالساعةُ قريبةٌ تأتي بغتة، فلا تغترّ بالمهلة، بل بادر بالعملِ قبل أن تفجأك الصيحة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للقاءِ الله، فالساعةُ قريبةٌ تأتي بغتة."},"action":{"text":"اعلم أنّ الله بيّن أنّ هؤلاء المكذّبين ما ينتظرون إلا صيحةً واحدةً — وهي نفخةُ الصورِ للبعثِ أو الهلاك — لا رجوعَ لها ولا مهلةَ ولا إفاقة «وما ينظر هؤلاء إلا صيحة واحدة ما لها من فواق»؛ فالساعةُ قريبةٌ تأتي بغتةً في صيحةٍ واحدة؛ فاستعدّ للقاءِ الله بالإيمانِ والعملِ الصالحِ قبل مجيئها؛ فلا تغترّ بالمهلةِ وطولِ الأمل؛ فالأجلُ قد يأتي بغتةً وأنت غافل؛ فبادر بالتوبةِ والعملِ قبل أن تفجأك الصيحةُ أو يحضرك الموت؛ فما بين أحدنا وبين الساعةِ إلا أن يموت؛ فمن مات فقد قامت قيامته؛ فاجعل نفسك مستعدًّا للرحيلِ في كلِّ لحظة؛ فالكيّسُ من دان نفسه وعمل لما بعد الموت؛ فلا تسوّف بالعمل؛ واعمل عملَ من يظنّ أنه لا يعيش إلا يومه؛ فالساعةُ آتيةٌ لا ريب فيها، قريبةٌ ولو استبعدها الغافلون؛ فاستعدّ لها بالإيمانِ والتقوى والعملِ الصالح."}},{"n":16,"reflection":{"text":"«وقالوا ربنا عجل لنا قطنا قبل يوم الحساب» — وقال المكذّبون استهزاءً: ربّنا عجّل لنا نصيبنا من العذابِ أو صحيفةَ أعمالنا قبل يومِ القيامة؛ ففي هذا استهزاؤهم بالوعيدِ واستعجالهم العذاب جهلًا؛ فاحذر الاستهزاءَ بوعيدِ الله واستعجالَه، فمن استهزأ بالعذابِ واستعجله سيندم حين يقع، فخذ الوعيدَ مأخذَ الجدّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بالوعيدِ واستعجالِ العذاب."},"action":{"text":"تأمّل استهزاءَ المكذّبين بالوعيدِ واستعجالهم العذاب جهلًا وتكذيبًا: ربّنا عجّل لنا نصيبنا من العذابِ أو صحيفةَ أعمالنا قبل يومِ الحساب «وقالوا ربنا عجل لنا قطنا قبل يوم الحساب»؛ فطلبوا تعجيلَ العذابِ استهزاءً وتكذيبًا بوقوعه؛ فاحذر الاستهزاءَ بوعيدِ الله واستعجالَ عذابه؛ فمن استهزأ بالعذابِ واستعجله جاهلًا سيندم أشدَّ الندمِ حين يقع به؛ فلا تستهن بوعيدِ الله ولا تأمن مكره؛ فلا يأمن مكرَ الله إلا القومُ الخاسرون؛ فخذ وعيدَ الله مأخذَ الجدِّ والحذر؛ واستعدّ للقائه بالإيمانِ والعمل؛ فالعاقلُ من خاف عذابَ الله فاجتنب أسبابه، لا من استعجله واستهزأ به؛ فإذا سمعت وعيدَ الله فخف واحذر وبادر بالتوبة؛ فمن استهزأ بوعيدِ الله فقد جهل عظمةَ الله وشدّةَ عقابه؛ فاجعل خوفك من عذابِ الله حافزًا للطاعةِ والاستعداد، لا مادّةً للاستهزاءِ والاستعجال."}},{"n":17,"reflection":{"text":"«اصبر على ما يقولون واذكر عبدنا داوود ذا الأيد إنه أواب» — اصبر يا محمدُ على أذى المكذّبين وأقوالهم، وتذكّر عبدنا داودَ صاحبَ القوّةِ في العبادةِ والبطش، إنه رجّاعٌ إلى الله بالتوبةِ والطاعة؛ ففي هذا الأمرُ بالصبرِ والتأسّي بالأنبياء؛ فاصبر على الأذى، وتأسَّ بالصالحين في الصبرِ والأوبةِ إلى الله، فذكرُ سيرِ الصالحين يعين على الصبرِ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى، والتأسّي بالأنبياءِ في الأوبةِ إلى الله."},"action":{"text":"اعلم أنّ الله أمر نبيَّه ﷺ بالصبرِ على أذى المكذّبين وأقوالهم، وأمره أن يتذكّر عبدَه داودَ صاحبَ القوّةِ في العبادةِ والصبرِ والطاعة، الذي كان أوّابًا رجّاعًا إلى الله في كلِّ أموره «اصبر على ما يقولون واذكر عبدنا داوود ذا الأيد إنه أواب»؛ ففي هذا الأمرُ بالصبرِ على الأذى والتأسّي بالأنبياءِ والصالحين؛ فاصبر على أذى الناسِ وأقوالهم كما صبر الأنبياء؛ وتأسَّ بالصالحين في صبرهم وقوّتهم في الطاعةِ وأوبتهم إلى الله؛ فذكرُ سيرِ الصالحين وأخبارهم يعين على الصبرِ والاقتداءِ بهم؛ فاجعل داودَ وأمثاله قدوةً لك في القوّةِ على الطاعةِ والرجوعِ إلى الله؛ فالأوّابُ هو الرجّاعُ إلى الله بالتوبةِ والذكرِ والطاعةِ كلّما أذنب أو غفل؛ فكن أوّابًا رجّاعًا إلى الله؛ وتقوَّ على العبادةِ والطاعةِ كما تقوّى داود؛ فبالصبرِ والأوبةِ إلى الله تُنال معيّتُه ومحبّته؛ فاصبر على الأذى، وعُد إلى الله في كلِّ حين."}},{"n":18,"reflection":{"text":"«إنا سخرنا الجبال معه يسبحن بالعشي والإشراق» — إنا سخّرنا الجبالَ تسبّح مع داودَ في المساءِ والصباح؛ ففي هذا بيانُ فضلِ الله على داودَ وأنّ الجمادَ يسبّح لله؛ فاعلم أنّ الكونَ كلَّه يسبّح لله، فاقتدِ بالجبالِ والطيرِ في تسبيحِ الله، وأكثر من تسبيحه في طرفيِ النهار، فالتسبيحُ عبادةُ الكونِ كلِّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من تسبيحِ الله، فالكونُ كلُّه يسبّح له."},"action":{"text":"اعلم أنّ الله أنعم على داودَ فسخّر معه الجبالَ تسبّح لله في العشيِّ والإشراقِ — أي في المساءِ والصباح — تأييدًا له وتفضيلًا «إنا سخرنا الجبال معه يسبحن بالعشي والإشراق»؛ فالجبالُ الجامدةُ تسبّح لله بأمره؛ فاعلم أنّ الكونَ كلَّه — جماده وحيّه — يسبّح لله ويحمده؛ وإن من شيءٍ إلا يسبّح بحمده ولكن لا تفقهون تسبيحهم؛ فاقتدِ بالجبالِ والطيرِ وسائرِ المخلوقاتِ في تسبيحِ الله؛ وأكثر من تسبيحِ الله وتحميده، لا سيّما في طرفيِ النهارِ صباحًا ومساءً؛ فسبّح بحمدِ ربك قبل طلوعِ الشمسِ وقبل الغروب؛ فالتسبيحُ عبادةُ الكونِ كلِّه، وهو ثقيلٌ في الميزان، حبيبٌ إلى الرحمن؛ فاعمر لسانك وقلبك بتسبيحِ الله في كلِّ حين؛ فإذا سبّحت فأنت في صفِّ الجبالِ والطيرِ والملائكةِ والكونِ كلِّه في تعظيمِ الله؛ فاجعل التسبيحَ وردك الدائمَ صباحًا ومساء."}},{"n":19,"reflection":{"text":"«والطير محشورة كل له أواب» — وسخّرنا الطيرَ مجموعةً معه تسبّح، كلٌّ من الجبالِ والطيرِ مطيعٌ رجّاعٌ إلى الله بالتسبيح؛ ففي هذا تمامُ نعمةِ الله على داودَ وانقيادُ الخلقِ لله؛ فتأمّل انقيادَ الطيرِ والجبالِ لله بالتسبيح، فكن أنت أولى بالانقيادِ والأوبةِ إلى الله، فالمخلوقاتُ كلُّها أوّابةٌ إلى ربها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانقيادُ لله والأوبةُ إليه، اقتداءً بالخلقِ المسبّح."},"action":{"text":"اعلم أنّ الله سخّر مع داودَ الطيرَ مجموعةً محشورةً تسبّح معه، وكلٌّ من الجبالِ والطيرِ مطيعٌ منقادٌ أوّابٌ رجّاعٌ إلى الله بالتسبيحِ والطاعة «والطير محشورة كل له أواب»؛ فتأمّل كيف انقادت الجبالُ والطيرُ لله تسبّحه وترجع إليه؛ فإذا كانت الجبالُ الصمُّ والطيرُ العُجمُ تسبّح لله وترجع إليه، فأنت — أيها الإنسانُ المكرّمُ العاقل — أولى بالانقيادِ لله والأوبةِ إليه والتسبيحِ له؛ فكن أوّابًا رجّاعًا إلى الله في كلِّ أمرك؛ فالمخلوقاتُ كلُّها منقادةٌ لله، مسبّحةٌ بحمده، راجعةٌ إليه؛ فلا تكن أقلَّ انقيادًا من الجبالِ والطير؛ بل سبّح الله، وأطعه، وارجع إليه في كلِّ حين؛ فاجعل قلبك ولسانك وجوارحك في طاعةِ الله وتسبيحه؛ فالأوبةُ إلى الله والانقيادُ له غايةُ العبودية؛ فاقتدِ بالكونِ المسبّحِ المنقادِ، وكن من الأوّابين إلى ربك."}},{"n":20,"reflection":{"text":"«وشددنا ملكه وآتيناه الحكمة وفصل الخطاب» — وقوّينا مُلكَ داودَ بالهيبةِ والنصرِ والجندِ، وأعطيناه الحكمةَ والنبوّةَ والفصلَ في القضاءِ والكلام؛ ففي هذا تمامُ فضلِ الله عليه؛ فاعلم أنّ التمكينَ والحكمةَ من فضلِ الله، فاسأله الحكمةَ والفصلَ في أمورك، واشكر ما آتاك من نعمة، فالحكمةُ خيرٌ كثير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحكمةِ من الله، وشكرُ نعمةِ التمكين."},"action":{"text":"اعلم أنّ الله أتمّ فضله على داودَ فقوّى مُلكه بالهيبةِ والنصرِ وكثرةِ الجند، وأعطاه الحكمةَ والنبوّةَ، وفصلَ الخطابِ — وهو الفصلُ في القضاءِ بين الناسِ والبيانُ الواضحُ في الكلام «وشددنا ملكه وآتيناه الحكمة وفصل الخطاب»؛ فالتمكينُ والحكمةُ والبيانُ من فضلِ الله ومنّته؛ فاعلم أنّ ما يؤتاه العبدُ من مُلكٍ وتمكينٍ وحكمةٍ وعلمٍ فمن فضلِ الله؛ فاسأل الله الحكمةَ والفصلَ والسدادَ في أمورك وأقوالك وأحكامك؛ فالحكمةُ خيرٌ كثير، ومن يؤت الحكمةَ فقد أوتي خيرًا كثيرًا؛ واشكر الله على ما آتاك من نعمةِ التمكينِ والعلمِ والبيان؛ فمن شكر النعمةَ زادها الله؛ واستعمل ما آتاك الله من قوّةٍ وحكمةٍ في طاعتِه ونفعِ عباده والحكمِ بالعدل؛ فالنعمُ أماناتٌ تُشكَر بحسنِ استعمالها؛ فاطلب الحكمةَ، واشكر النعمة، واستعملها في مرضاةِ الله."}}]},{"title":"خصومةُ الملكينِ، وحكمُ داودَ وتوبتُه، واستخلافُه، وحكمةُ الخلقِ وتدبّرُ القرآن","range":[21,29],"theme":"قصةُ الخصمينِ اللذينِ تسوّرا محرابَ داودَ يطلبان الحكمَ بالعدل، وشكوى صاحبِ النعجةِ الواحدةِ من بغيِ صاحبِ التسعِ والتسعين، وحكمُ داودَ ثم علمُه أنه فُتِن فاستغفر وخرّ راكعًا وأناب فغُفِر له وله زلفى، ووصيّتُه بالحكمِ بالحقِّ وتركِ الهوى وتذكّرِ يومِ الحساب، وأنّ خلقَ السماءِ والأرضِ بحقٍّ لا باطلًا، وأنّ الله لا يسوّي بين المؤمنِ والمفسدِ، وأنّ القرآنَ أُنزِل ليُتدبَّر","verses":[{"n":21,"reflection":{"text":"«وهل أتاك نبأ الخصم إذ تسوروا المحراب» — وهل بلغك خبرُ الخصمِ حين تسلّقوا على داودَ محرابه وموضعَ عبادته؟ ففي هذا تشويقٌ لقصّةٍ فيها عبرة؛ فتهيّأ للاعتبارِ بقصصِ القرآن، فكلُّ قصّةٍ فيها عبرةٌ ودرس، فاقرأ قصصَ القرآنِ بقلبٍ حاضرٍ متدبّرٍ لتأخذ عبرتها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التهيّؤُ للاعتبارِ بقصصِ القرآنِ وأخذِ عبرتها."},"action":{"text":"اعلم أنّ الله شوّق نبيَّه لسماعِ قصّةِ الخصمِ الذين تسلّقوا على داودَ سورَ محرابه وموضعِ عبادته ليحتكموا إليه «وهل أتاك نبأ الخصم إذ تسوروا المحراب»؛ فهذا الاستفهامُ للتشويقِ والتنبيهِ على أنّ فيما يأتي عبرةً ودرسًا؛ فتهيّأ للاعتبارِ بقصصِ القرآنِ العظيم؛ فما قصّ الله علينا القصصَ إلا لنعتبر ونتّعظ ونثبّت به قلوبنا؛ فكلُّ قصّةٍ في القرآنِ فيها عبرةٌ ودرسٌ وحكمة؛ فاقرأ قصصَ القرآنِ بقلبٍ حاضرٍ متدبّرٍ متأمّل، لا بقلبٍ غافلٍ لاهٍ؛ واستخلص من كلِّ قصّةٍ عبرتها ودرسها وما تدلّ عليه من أسماءِ الله وصفاتِه وسننِه في خلقه؛ فقصّةُ داودَ فيها درسٌ في العدلِ في الحكم، والحذرِ من الاستعجالِ فيه، وسرعةِ الأوبةِ إلى الله عند الزلل؛ فاجعل قصصَ القرآنِ زادًا لإيمانك وعبرةً لقلبك؛ فلقد كان في قصصهم عبرةٌ لأولي الألباب."}},{"n":22,"reflection":{"text":"«إذ دخلوا على داوود ففزع منهم قالوا لا تخف خصمان بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط واهدنا إلى سواء الصراط» — حين دخلوا عليه فجأةً ففزع، فطمأنوه: لا تخف، نحن خصمان بغى بعضنا على بعض، فاحكم بيننا بالعدل ولا تجُر، وأرشدنا إلى وسطِ الطريق؛ ففي هذا طلبُ الحكمِ بالحقِّ والعدل؛ فاطلب الحكمَ بالعدلِ في خصوماتك، واحكم بالحقِّ إن حكّمت، ولا تجُر، فالعدلُ في الحكمِ من أعظمِ القرب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحكمِ بالعدل، والحكمُ بالحقِّ دون جورٍ ولا شطط."},"action":{"text":"تأمّل قصّةَ الخصمينِ اللذين دخلا على داودَ فجأةً في محرابه ففزع منهم، فطمأنوه: لا تخف، إنما نحن خصمان بغى بعضنا على بعض، فاحكم بيننا بالحقِّ والعدل، ولا تجُر ولا تَمِل، وأرشدنا إلى وسطِ الطريقِ وسوائه «إذ دخلوا على داوود ففزع منهم قالوا لا تخف خصمان بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط واهدنا إلى سواء الصراط»؛ فطلبوا منه الحكمَ بالعدلِ والإرشادَ إلى الحق؛ فاطلب أنت الحكمَ بالعدلِ في خصوماتك، وارضَ بحكمِ الحقِّ عليك ولك؛ وإن حكّمك الناسُ فاحكم بينهم بالحقِّ والعدل، ولا تجُر ولا تمِل مع أحدٍ لهوًى أو قرابةٍ أو رشوة؛ فالعدلُ في الحكمِ من أعظمِ القرباتِ إلى الله؛ فالمقسطون على منابرَ من نورٍ عند الله؛ فاحرص على العدلِ في كلِّ حكمٍ تحكمه، ولو على نفسك وأقربِ الناسِ إليك؛ فلا تحملنّك عداوةُ قومٍ على ألا تعدلوا، اعدلوا هو أقربُ للتقوى؛ فالعدلُ ميزانُ الله في الأرض؛ فاجعله شعارك في أحكامك ومعاملاتك."}},{"n":23,"reflection":{"text":"«إن هذا أخي له تسع وتسعون نعجة ولي نعجة واحدة فقال أكفلنيها وعزني في الخطاب» — قال أحدهما: إنّ هذا أخي له تسعٌ وتسعون نعجة ولي واحدة، فقال: ضمّها إليّ، وغلبني في الحجّةِ والكلام؛ ففي هذا صورةٌ للبغيِ والطمعِ في حقِّ الغير؛ فاحذر الطمعَ في حقوقِ الناسِ والبغيَ عليهم، واقنع بما آتاك الله، فالطمعُ في حقِّ الغيرِ ظلمٌ وبغي، والقناعةُ كنزٌ لا يفنى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الطمعِ في حقوقِ الناسِ والبغيِ عليهم، والقناعة."},"action":{"text":"تأمّل شكوى أحدِ الخصمينِ لداود: إنّ هذا أخي له تسعٌ وتسعون نعجة ولي نعجةٌ واحدة، فقال لي: ضمّها إليّ واتركها لي، وغلبني وقهرني في الحجّةِ والخطاب «إن هذا أخي له تسع وتسعون نعجة ولي نعجة واحدة فقال أكفلنيها وعزني في الخطاب»؛ فهذه صورةٌ للبغيِ والطمعِ في حقِّ الغير: صاحبُ التسعِ والتسعين يطمع في نعجةِ أخيه الواحدة؛ فاحذر الطمعَ في حقوقِ الناسِ والبغيَ عليهم مهما كثر ما عندك؛ فمن كان عنده الكثيرُ ثم طمع في القليلِ الذي عند غيره فهو الباغي الظالم؛ فاقنع بما آتاك الله، ولا تمدّنّ عينيك إلى ما متّع الله به غيرك؛ فالقناعةُ كنزٌ لا يفنى، وغنًى لا ينفد؛ فالغنى غنى النفس؛ فمن قنع بما رزقه الله استغنى وسعد، ومن طمع في حقوقِ الناسِ شقي وأثم؛ فطهّر قلبك من الطمعِ والبغي؛ واحفظ حقوقَ الناسِ كما تحبّ أن تُحفَظ حقوقك؛ فالبغيُ مرتعُه وخيم، وعاقبتُه سيّئة."}},{"n":24,"reflection":{"text":"«قال لقد ظلمك بسؤال نعجتك إلى نعاجه وإن كثيرا من الخلطاء ليبغي بعضهم على بعض إلا الذين آمنوا وعملوا الصالحات وقليل ما هم وظن داوود أنما فتناه فاستغفر ربه وخر راكعا وأناب» — حكم داودُ بأنّ الطالبَ ظلمه، ونبّه أنّ كثيرًا من الشركاءِ يبغي بعضهم على بعض إلا المؤمنين الصالحين وقليلٌ هم، ثم علم داودُ أنّا اختبرناه (بحكمِه قبل سماعِ الخصمِ الآخر) فاستغفر وسجد وتاب؛ ففي هذا سرعةُ أوبةِ داودَ عند الزلل؛ فبادر بالاستغفارِ والتوبةِ عند الزلل، واسجد لله منيبًا، فالأوّابُ من رجع إلى الله فورَ زلّته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالاستغفارِ والتوبةِ والإنابةِ عند الزلل."},"action":{"text":"تأمّل حكمَ داودَ ثم أوبتَه: قال للطالبِ لقد ظلمك أخوك بطلبِ نعجتك ليضمّها إلى نعاجه، ونبّه أنّ كثيرًا من الشركاءِ والخلطاءِ يبغي بعضهم على بعض، إلا المؤمنين الصالحين وقليلٌ ما هم؛ ثم علم داودُ أنّ الله اختبره بهذه الحادثة — إذ حكم لأحدهما قبل أن يسمع من الآخر — فبادر بالاستغفارِ وخرّ ساجدًا وأناب إلى الله «قال لقد ظلمك... وظن داوود أنما فتناه فاستغفر ربه وخر راكعا وأناب»؛ ففي هذا سرعةُ أوبةِ داودَ ورجوعِه إلى الله عند الزلل؛ فتعلّم من داودَ المبادرةَ بالاستغفارِ والتوبةِ والإنابةِ عند الزللِ والخطأ؛ فلا تصرّ على زلّة، ولا تسوّف بالتوبة؛ بل بادر فورَ وقوعِ الخطأ بالاستغفارِ والرجوعِ إلى الله؛ واسجد لله منيبًا خاشعًا؛ فالسجودُ من أعظمِ أسبابِ القربِ من الله؛ (وهذا موضعُ سجدةِ تلاوة)؛ فالأوّابُ هو من يرجع إلى الله فورَ زلّته بالتوبةِ والإنابة؛ فكن أوّابًا لا مصرًّا؛ فمن بادر بالتوبةِ غفر الله له كما غفر لداود؛ واحذر أيضًا الحكمَ قبل سماعِ الطرفين؛ فالعدلُ أن تسمع من الخصمين قبل أن تحكم."}},{"n":25,"reflection":{"text":"«فغفرنا له ذلك وإن له عندنا لزلفى وحسن مآب» — فغفرنا لداودَ زلّته، وإنّ له عندنا لقربةً ومنزلةً رفيعةً وحسنَ مرجع؛ ففي هذا ثمرةُ التوبةِ: المغفرةُ والقربةُ ورفعةُ المنزلة؛ فاعلم أنّ التوبةَ الصادقةَ تجلب المغفرةَ والقربَ من الله، فتب إلى الله صادقًا، فالتائبُ يرفعه الله ويقرّبه، فلا تيأس من رحمةِ الله بعد الزلل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في ثمرةِ التوبة: المغفرةُ والقربُ ورفعةُ المنزلة."},"action":{"text":"اعلم أنّ الله غفر لداودَ زلّته لمّا تاب وأناب، بل رفع منزلته فجعل له عنده قربةً ومكانةً رفيعةً وحسنَ مرجعٍ ومآب «فغفرنا له ذلك وإن له عندنا لزلفى وحسن مآب»؛ فهذه ثمرةُ التوبةِ الصادقة: المغفرةُ للذنب، والقربُ من الله، ورفعةُ المنزلة، وحسنُ العاقبة؛ فاعلم أنّ التوبةَ الصادقةَ لا تمحو الذنبَ فحسب، بل ترفع صاحبها وتقرّبه من الله؛ فالتائبُ من الذنبِ كمن لا ذنبَ له، وقد يرفعه الله بتوبتِه فوقَ منزلتِه قبلها؛ فتب إلى الله توبةً صادقةً نصوحًا؛ ولا تيأس من رحمةِ الله بعد الزللِ والذنب؛ فإنّ الله يحبّ التوّابين ويقرّبهم؛ فمن تاب تاب الله عليه، ورفع منزلته، وأحسن مرجعه؛ فلا تجعل الذنبَ يقنّطك من رحمةِ الله؛ بل اجعله بابًا للتوبةِ والأوبةِ والقرب؛ فالله يفرح بتوبةِ عبده؛ فبادر بالتوبة، وأحسن الظنَّ بالله، وارجُ مغفرته وقربه وحسنَ مآبه؛ فرحمةُ الله وسعت كلَّ شيء، وهي قريبةٌ من التائبين المنيبين."}},{"n":26,"reflection":{"text":"«يا داوود إنا جعلناك خليفة في الأرض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله إن الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب» — يا داودُ جعلناك خليفةً حاكمًا في الأرض، فاحكم بين الناسِ بالعدل، ولا تتّبع الهوى فيصرفك عن طريقِ الله؛ إنّ الضالّين عن سبيلِ الله لهم عذابٌ شديدٌ بنسيانهم يومَ الحساب؛ ففي هذا وصيّةُ الحاكمِ بالعدلِ وتركِ الهوى؛ فاحكم بالحقِّ في كلِّ ما وُلّيت، واحذر اتّباعَ الهوى، فإنه يُضلّ عن سبيلِ الله، وتذكّر يومَ الحسابِ ليستقيم عملك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحكمُ بالحقِّ وتركُ الهوى، وتذكّرُ يومِ الحسابِ في العمل."},"action":{"text":"تأمّل وصيّةَ الله لداودَ الخليفةِ الحاكم: يا داودُ إنا جعلناك خليفةً في الأرضِ تحكم بين الناس، فاحكم بينهم بالحقِّ والعدل، ولا تتّبع الهوى في حكمك فيصرفك عن سبيلِ الله؛ إنّ الذين يضلّون عن سبيلِ الله لهم عذابٌ شديدٌ بسببِ نسيانهم يومَ الحساب «يا داوود إنا جعلناك خليفة في الأرض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله...»؛ ففي هذا وصيّةٌ جامعةٌ لكلِّ من وُلّي أمرًا: الحكمُ بالحقِّ، وتركُ اتّباعِ الهوى؛ فاحكم بالحقِّ والعدلِ في كلِّ ما وُلّيت من أمرِ نفسك وأهلك ومن تحت يدك؛ واحذر اتّباعَ الهوى في أحكامك وأقوالك وأفعالك؛ فإنّ الهوى يُضلّ عن سبيلِ الله؛ فما ذُكِر الهوى في القرآنِ إلا ذُمّ؛ فمن حكّم هواه ضلّ، ومن حكّم الحقَّ اهتدى؛ وتذكّر يومَ الحسابِ دائمًا؛ فتذكّره يقوّم العملَ ويردع عن الهوى والظلم؛ فمن نسي يومَ الحسابِ ضلّ وظلم، ومن استحضره استقام وعدل؛ فاجعل الحقَّ إمامك، والحسابَ نصبَ عينيك؛ فبذلك تستقيم وتنجو من العذابِ الشديد."}},{"n":27,"reflection":{"text":"«وما خلقنا السماء والأرض وما بينهما باطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار» — وما خلقنا السماءَ والأرضَ وما بينهما عبثًا بلا حكمةٍ ولا بعثٍ ولا جزاء، ذلك ظنُّ الكافرين، فويلٌ لهم من النار؛ ففي هذا تقريرُ حكمةِ الخلقِ والبعثِ والجزاء؛ فاعلم أنّ خلقك لحكمةٍ وغاية، لا عبثًا، فاستعدّ للقاءِ الله والجزاء، ولا تظنّ أنّ الحياةَ عبثٌ بلا حساب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ حكمةِ الخلقِ والبعث، والاستعدادُ للجزاء."},"action":{"text":"اعلم أنّ الله ما خلق السماءَ والأرضَ وما بينهما عبثًا وباطلًا بلا حكمةٍ ولا غايةٍ ولا بعثٍ ولا جزاء؛ فمن ظنّ ذلك فهو ظنُّ الكافرين، فويلٌ لهم من النارِ التي أعدّها لهم «وما خلقنا السماء والأرض وما بينهما باطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار»؛ فالكونُ مخلوقٌ بحكمةٍ بالغة، والإنسانُ مخلوقٌ لغايةٍ عظيمة: عبادةِ الله ثم البعثِ والجزاء؛ فاعلم أنّ خلقك لم يكن عبثًا، وأنك لن تُترَك سدًى بلا أمرٍ ولا نهيٍ ولا حسابٍ ولا جزاء؛ أفحسبتم أنما خلقناكم عبثًا وأنكم إلينا لا ترجعون؟ فاستعدّ للقاءِ الله والجزاءِ على عملك؛ ولا تظنّ أنّ الحياةَ عبثٌ ولهوٌ بلا حسابٍ ولا مآل؛ فمن آمن بحكمةِ الخلقِ والبعثِ استقام وعمل، ومن ظنّ العبثَ لها وأنكر البعثَ ضلّ وفسق؛ فتأمّل في حكمةِ خلقِ الله لتزداد إيمانًا؛ واعمل لغايةِ وجودك: عبادةِ الله والاستعدادِ للقائه؛ فالخلقُ بحقٍّ لا بباطل، والحياةُ لغايةٍ لا لعبث؛ فاعمل لما خُلِقت له."}},{"n":28,"reflection":{"text":"«أم نجعل الذين آمنوا وعملوا الصالحات كالمفسدين في الأرض أم نجعل المتقين كالفجار» — أنسوّي بين المؤمنين العاملين الصالحاتِ والمفسدين في الأرض؟ أم نسوّي بين المتّقين والفجّار؟ ففي هذا تقريرُ عدلِ الله وأنه لا يسوّي بين المؤمنِ والكافر؛ فاعلم أنّ الله لا يسوّي بين المحسنِ والمسيء، فاعمل صالحًا لتكون من المتّقين المكرمين، فالجزاءُ يفرّق بين الفريقين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بعدلِ الله، والعملُ الصالحُ لتمييزِ المتّقين."},"action":{"text":"تأمّل تقريرَ الله لعدلِه وحكمته: أيليق بعدلِ الله وحكمته أن يسوّي بين الذين آمنوا وعملوا الصالحاتِ والمفسدين في الأرض؟ أم يسوّي بين المتّقين والفجّار؟ «أم نجعل الذين آمنوا وعملوا الصالحات كالمفسدين في الأرض أم نجعل المتقين كالفجار»؛ فحاشا لله أن يسوّي بينهم؛ فهذا مقتضى حكمتِه وعدله؛ فلا بدّ من بعثٍ وجزاءٍ يُميّز فيه المحسنُ من المسيء؛ فاعلم أنّ الله لا يسوّي بين المؤمنِ والكافر، ولا بين المتّقي والفاجر، ولا بين المصلحِ والمفسد؛ فلكلٍّ جزاؤه اللائقُ به؛ فالمؤمنون في نعيم، والفجّار في جحيم؛ فاعمل صالحًا واتّق الله لتكون من المؤمنين المتّقين المكرمين؛ ولا تكن من المفسدين الفجّار المعذّبين؛ فالجزاءُ يفرّق بين الفريقين تفريقًا عظيمًا؛ فاختر لنفسك أيَّ الفريقين تكون؛ فالعملُ الصالحُ والتقوى سبيلُ الفوز، والفسادُ والفجورُ سبيلُ الخسران؛ فبادر بالإيمانِ والعملِ الصالحِ والتقوى، لتكون من أهلِ النعيمِ لا من أهلِ الجحيم؛ فعدلُ الله يقتضي التمييزَ بين المتّقي والفاجر."}},{"n":29,"reflection":{"text":"«كتاب أنزلناه إليك مبارك ليدبروا آياته وليتذكر أولو الألباب» — هذا القرآنُ كتابٌ مباركٌ كثيرُ الخيرِ أنزلناه إليك ليتدبّر الناسُ آياته ويتذكّر أصحابُ العقولِ السليمة؛ ففي هذا بيانُ الغايةِ من إنزالِ القرآن: التدبّرُ والتذكّر؛ فاجعل غايتك من القرآنِ التدبّرَ والتذكّرَ والعمل، لا مجرّدَ التلاوة، فالقرآنُ أُنزِل ليُتدبَّر ويُعمَل به، فتدبّر آياته بقلبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ القرآنِ والتذكّرُ به، فتلك غايةُ إنزاله."},"action":{"text":"اعلم أنّ الله بيّن الغايةَ من إنزالِ القرآن: أنه كتابٌ مباركٌ كثيرُ الخيرِ والبركة، أنزله ليتدبّر الناسُ آياته ويفهموا معانيها، وليتذكّر بها أصحابُ العقولِ السليمة «كتاب أنزلناه إليك مبارك ليدبروا آياته وليتذكر أولو الألباب»؛ فالغايةُ من القرآنِ التدبّرُ والتذكّرُ والعمل، لا مجرّدُ التلاوةِ بلا فهم؛ فاجعل غايتك من قراءةِ القرآنِ التدبّرَ لآياته، والتذكّرَ بمواعظه، والعملَ بأحكامه؛ فأفلا يتدبّرون القرآنَ أم على قلوبٍ أقفالها؟ فلا تهذّ القرآنَ هذًّا بلا تدبّر؛ بل اقرأه بترتيلٍ وتأمّل، وقف عند آياته، وتفكّر في معانيها؛ فالتدبّرُ يفتح للقلبِ كنوزَ القرآنِ وأنواره؛ فمن تدبّر القرآنَ انتفع به واهتدى، ومن قرأه بلا تدبّرٍ فاته خيرٌ كثير؛ فاجعل لك وقفاتٍ تدبّريّةً مع القرآن؛ وتذكّر بما فيه من الوعدِ والوعيدِ والأمثالِ والقصص؛ فالقرآنُ مأدبةُ الله، فتعلّموا من مأدبته؛ فتدبّره بقلبٍ حاضرٍ، واعمل بمقتضاه؛ فبالتدبّرِ والعملِ تُنال بركةُ القرآن."}}]},{"title":"سليمانُ: مُلكُه وأوبتُه وتسخيرُ الريحِ والشياطين، وأيوبُ: بلاؤه وصبرُه وفرجُه","range":[30,44],"theme":"هبةُ سليمانَ لداودَ ومدحُه بالأوبة، وقصةُ الخيلِ التي شغلته فآثر ذكرَ ربه، وفتنتُه وإنابتُه ودعاؤه بمُلكٍ لا ينبغي لأحدٍ بعده، وتسخيرُ الريحِ والشياطينِ البنّائين والغوّاصين له وتفويضُه في العطاء، وأنّ له عند الله زلفى؛ ثم أيوبُ ونداؤه ربه من مسِّ الضرّ، وأمرُه بركضِ الأرضِ فنبعت عينُ الشفاء، وتعويضُه أهله ومثلهم، وأخذُه الضغثَ برًّا بيمينه، وثناءُ الله عليه بالصبرِ والأوبة","verses":[{"n":30,"reflection":{"text":"«ووهبنا لداوود سليمان نعم العبد إنه أواب» — ووهبنا لداودَ ابنه سليمانَ نبيًّا، نِعم العبدُ سليمان، إنه أوّابٌ رجّاعٌ إلى الله؛ ففي هذا نعمةُ الذريةِ الصالحةِ ومدحُ الأوّاب؛ فاسأل الله الذريةَ الصالحة، وكن أوّابًا رجّاعًا إلى الله، فمدحُ الله لسليمانَ بالأوبةِ يبيّن أنّ خيرَ العبادِ أوّابهم إلى الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الذريةِ الصالحة، وكونُ العبدِ أوّابًا إلى الله."},"action":{"text":"اعلم أنّ الله وهب لداودَ ابنه سليمانَ نبيًّا كريمًا، وأثنى عليه فقال: نِعم العبدُ سليمان، إنه أوّابٌ رجّاعٌ إلى الله بالتوبةِ والذكرِ والطاعة «ووهبنا لداوود سليمان نعم العبد إنه أواب»؛ ففي هذا نعمةُ الذريةِ الصالحةِ التي تخلف أباها في الخير، ومدحُ العبدِ الأوّاب؛ فاسأل الله الذريةَ الصالحةَ التي تقرّ بها عينك وتنفعك بعد موتك؛ فالولدُ الصالحُ من أعظمِ النعم؛ وكن أنت أوّابًا رجّاعًا إلى الله في كلِّ أمرك؛ فقد أثنى الله على داودَ وسليمانَ بالأوبة؛ فخيرُ العبادِ أوّابهم إلى الله؛ فالأوّابُ هو الرجّاعُ إلى الله بالتوبةِ كلّما أذنب، وبالذكرِ كلّما غفل، وبالطاعةِ كلّما فتر؛ فاجعل الأوبةَ إلى الله دأبك؛ كلّما زللت فتب، وكلّما غفلت فاذكر، وكلّما فترت فانشط؛ فبالأوبةِ المستمرّةِ إلى الله تُنال محبّته والثناءُ منه؛ فاطلب الذريةَ الصالحة، وكن عبدًا أوّابًا؛ فذلك سبيلُ الخيرِ في الدنيا والآخرة."}},{"n":31,"reflection":{"text":"«إذ عرض عليه بالعشي الصافنات الجياد» — حين عُرِض على سليمانَ في آخرِ النهارِ الخيلُ الأصيلةُ السريعةُ الواقفةُ على ثلاثٍ طرفَ الرابعة؛ ففي هذا ذكرُ نعمةِ الله على سليمانَ بالخيلِ التي أعدّها للجهاد؛ فاعلم أنّ اقتناءَ ما يُعين على طاعةِ الله وجهادِ عدوّه قربة، فاتّخذ من أسبابِ القوّةِ ما يُعينك على طاعةِ الله ونصرةِ دينه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّخاذُ أسبابِ القوّةِ لما يُعين على طاعةِ الله وجهادِ عدوّه."},"action":{"text":"اعلم أنّ الله ذكر من نعمِه على سليمانَ أن عُرِض عليه في آخرِ النهارِ الخيلُ الصافناتُ الجيادُ — وهي الخيلُ الأصيلةُ الكريمةُ السريعةُ التي تقف على ثلاثِ قوائمَ وتُقلّ الرابعة — التي أعدّها للجهادِ في سبيلِ الله «إذ عرض عليه بالعشي الصافنات الجياد»؛ فكانت الخيلُ عنده عُدّةً للجهادِ وطاعةِ الله؛ فاعلم أنّ اقتناءَ ما يُعين على طاعةِ الله وجهادِ عدوّه وإقامةِ دينه قربةٌ وطاعة؛ فاتّخذ من أسبابِ القوّةِ والعُدّةِ ما يُعينك على طاعةِ الله ونصرةِ دينه؛ وأعدّوا لهم ما استطعتم من قوّةٍ ومن رباطِ الخيل؛ فالقوّةُ المرصودةُ لطاعةِ الله ونصرةِ الحقِّ محمودة؛ فاجعل ما تملكه من قوّةٍ ومالٍ وأسبابٍ في طاعةِ الله ونفعِ دينه وعباده؛ فنعمُ الله أماناتٌ تُستعمَل في مرضاته؛ فمن سخّر نعمَ الله في طاعتِه بورك له فيها؛ فالخيلُ وكلُّ عُدّةٍ خيرٌ إذا صُرِفت في سبيلِ الله؛ فاتّخذ العُدّةَ، واجعل غايتها طاعةَ الله ونصرةَ دينه."}},{"n":32,"reflection":{"text":"«فقال إني أحببت حب الخير عن ذكر ربي حتى توارت بالحجاب» — فقال سليمانُ: إني أحببتُ حبَّ الخيلِ (الخير) لأجلِ ذكرِ ربي وجهادِ عدوّه، حتى غابت الشمسُ بالحجاب (أو: شُغِل بها عن الذكرِ فتداركها)؛ ففي هذا حرصُ سليمانَ على ألا يشغله شيءٌ عن ذكرِ الله؛ فاحذر أن تشغلك محابُّ الدنيا عن ذكرِ الله وطاعته، بل اجعل حبَّك لها تابعًا لطاعةِ الله، فلا تدع شيئًا يصرفك عن ذكرِ ربك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن تشغلَ محابُّ الدنيا عن ذكرِ الله."},"action":{"text":"تأمّل قولَ سليمانَ حين عُرِضت عليه الخيلُ حتى غابت الشمس: إني أحببتُ حبَّ الخيرِ — وهي الخيلُ — لأجلِ ذكرِ ربي والجهادِ في سبيله «فقال إني أحببت حب الخير عن ذكر ربي حتى توارت بالحجاب»؛ وفي معناه أنّ حبَّه لها كان لطاعةِ الله لا لهوى النفس؛ وقيل: شُغِل بعرضها عن وردٍ من ذكرِ الله حتى غابت الشمسُ فتداركه؛ ففي القصّةِ حرصُ سليمانَ على ألا يشغله شيءٌ من الدنيا عن ذكرِ الله وطاعته؛ فاحذر أن تشغلك محابُّ الدنيا — مالٌ أو ولدٌ أو تجارةٌ أو متاع — عن ذكرِ الله وطاعتِه وواجباتِ دينك؛ يا أيها الذين آمنوا لا تلهكم أموالكم ولا أولادكم عن ذكرِ الله؛ فاجعل حبَّك لما تحبُّ من الدنيا تابعًا لطاعةِ الله ومرضاته، لا مقدّمًا عليها؛ فإن أحببت شيئًا من متاعِ الدنيا فأحبَّه لتستعين به على طاعةِ الله؛ ولا تدع شيئًا يصرفك عن ذكرِ ربك وأداءِ فرائضه؛ فمن قدّم محابَّ الدنيا على ذكرِ الله خسر، ومن جعلها عونًا على طاعتِه ربح؛ فراقب قلبك: ألا يغلبه حبُّ الدنيا على حبِّ الله وذكره."}},{"n":33,"reflection":{"text":"«ردوها علي فطفق مسحا بالسوق والأعناق» — قال سليمانُ: ردّوا الخيلَ عليّ، فأخذ يمسح سوقها وأعناقها (كرامةً لها لأنها في سبيلِ الله، أو ذبحها قربةً لله لمّا شغلته عن الذكر)؛ ففي هذا إيثارُ سليمانَ طاعةَ الله على محبوبه؛ فقدّم طاعةَ الله ومرضاته على محابّك، وإذا شغلك شيءٌ عن الله فجاهد نفسك فيه، فإيثارُ الله على المحبوبِ من كمالِ العبودية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ طاعةِ الله على المحبوب، ومجاهدةُ ما يشغل عنه."},"action":{"text":"تأمّل موقفَ سليمانَ حين شغلته الخيلُ (على أحدِ التفسيرين) عن ذكرِ ربه: قال ردّوها عليّ، فأخذ يمسح بسيفِه سوقها وأعناقها فذبحها قربةً لله؛ أو أخذ يمسحها كرامةً لها لأنها معدّةٌ لسبيلِ الله «ردوها علي فطفق مسحا بالسوق والأعناق»؛ فعلى تفسيرِ الذبحِ آثر سليمانُ طاعةَ الله ومرضاته على محبوبه من الخيل، لمّا خشي أن تشغله؛ ففي هذا إيثارُ العبدِ طاعةَ الله على أحبِّ الأشياءِ إليه؛ فقدّم طاعةَ الله ومرضاته على محابّك ومشتهياتك؛ وإذا وجدت شيئًا يشغلك عن الله وطاعتِه فجاهد نفسك فيه، وقدّم حقَّ الله عليه؛ فإيثارُ الله على المحبوباتِ من كمالِ العبوديةِ والمحبّة؛ فما آثر عبدٌ رضا الله على هواه إلا عوّضه الله خيرًا؛ فمن ترك شيئًا لله عوّضه الله خيرًا منه؛ فراقب محابّك: إن زاحمت طاعةَ الله فقدّم طاعتَه؛ فالمؤمنُ الصادقُ يقدّم محبّةَ الله على كلِّ محبوب؛ فاجعل رضا الله فوق كلِّ شيء؛ فبإيثارِه تُنال المحبّةُ والقربُ والعوض."}},{"n":34,"reflection":{"text":"«ولقد فتنا سليمان وألقينا على كرسيه جسدا ثم أناب» — ولقد اختبرنا سليمانَ وألقينا على كرسيّه جسدًا (ابتلاءً)، ثم رجع إلى الله بالتوبةِ والإنابة؛ ففي هذا ابتلاءُ الله لأنبيائه وسرعةُ أوبتهم؛ فاعلم أنّ الابتلاءَ يصيب الصالحين، والعبرةُ بالأوبةِ إلى الله بعده، فإذا ابتُليت فأنب إلى الله، فالمؤمنُ يرجع إلى ربه في كلِّ حال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأوبةُ إلى الله بعد الابتلاء، وإدراكُ أنه يصيب الصالحين."},"action":{"text":"اعلم أنّ الله ابتلى نبيَّه سليمانَ واختبره، وألقى على كرسيّه جسدًا في قصّةٍ من قصصِ الابتلاء، ثم رجع سليمانُ إلى الله بالتوبةِ والإنابةِ والأوبة «ولقد فتنا سليمان وألقينا على كرسيه جسدا ثم أناب»؛ ففي هذا أنّ الابتلاءَ والفتنةَ تصيب حتى الأنبياءَ والصالحين، حكمةً من الله وتمحيصًا ورفعةً؛ فالعبرةُ ليست في وقوعِ الابتلاء، بل في الأوبةِ إلى الله بعده؛ فاعلم أنّ الابتلاءَ سنّةُ الله في عباده، يصيب الصالحين قبل غيرهم؛ فإذا ابتُليت بشيءٍ فأنب إلى الله، وارجع إليه بالتوبةِ والدعاءِ والتسليم؛ فالمؤمنُ يرجع إلى ربه في السرّاءِ والضرّاء، وفي البلاءِ والعافية؛ فلا يُقنّطك الابتلاءُ من رحمةِ الله، ولا يحملك على السخطِ والجزع؛ بل اجعله بابًا للأوبةِ والإنابةِ والقربِ من الله؛ فمن أناب إلى الله بعد الابتلاءِ رفعه الله وقرّبه؛ فكن أوّابًا منيبًا في كلِّ حال؛ فالأوبةُ إلى الله عزُّ العبدِ وسعادته."}},{"n":35,"reflection":{"text":"«قال رب اغفر لي وهب لي ملكا لا ينبغي لأحد من بعدي إنك أنت الوهاب» — قال سليمانُ: ربِّ اغفر لي، وأعطني مُلكًا لا يكون لأحدٍ بعدي، إنك أنت كثيرُ العطاء؛ ففي هذا بدؤه بالاستغفارِ ثم سؤالِ الله من فضله؛ فابدأ دعاءك بالاستغفارِ والتوبة، ثم اسأل الله من فضله، وأخلص سؤالك لله الوهّاب، فمن قدّم التوبةَ استجيب دعاؤه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"البدءُ بالاستغفار، ثم سؤالُ الله من فضلِه الواسع."},"action":{"text":"تأمّل دعاءَ سليمانَ حين أناب: بدأ بالاستغفارِ فقال: ربِّ اغفر لي، ثم سأل الله مُلكًا خاصًّا لا يكون لأحدٍ من بعده معجزةً له، معترفًا بأنّ الله هو الوهّابُ كثيرُ العطاء «قال رب اغفر لي وهب لي ملكا لا ينبغي لأحد من بعدي إنك أنت الوهاب»؛ فقدّم الاستغفارَ والتوبةَ على سؤالِ حاجته، وختم بالثناءِ على الله بالوهّاب؛ فابدأ دعاءك بالاستغفارِ والتوبةِ والثناءِ على الله؛ ثم اسأله حاجتك من فضله؛ فتقديمُ الاستغفارِ والثناءِ من أسبابِ إجابةِ الدعاء؛ وأخلص سؤالك لله وحده، فهو الوهّابُ الذي لا ينفد عطاؤه؛ فلا تسأل إلا الله، ولا ترجُ إلا فضله؛ فمن قدّم التوبةَ والاستغفارَ ثم دعا كان أرجى لإجابته؛ ولا حرج أن تسأل الله من واسعِ فضله ما شئت من خيرِ الدنيا والآخرة؛ فخزائنه ملأى لا تغيضها النفقة؛ فألحّ على الله في الدعاء، وابدأه بالاستغفارِ والثناء، واختمه بالتوسّلِ بأسمائه الحسنى؛ فالوهّابُ يعطي من سأله بأدبٍ ورجاء؛ فتأدّب في دعائك، وأخلصه لله، وأحسن الظنَّ بعطائه."}},{"n":36,"reflection":{"text":"«فسخرنا له الريح تجري بأمره رخاء حيث أصاب» — فسخّرنا لسليمانَ الريحَ تجري بأمره ليّنةً حيث قصد وأراد؛ ففي هذا إجابةُ دعائه وتمامُ فضلِ الله عليه؛ فاعلم أنّ الله يسخّر لعباده ما يشاء بفضله، فاسأل الله من فضله وثق بقدرته، فمن أخلص لله وأناب إليه سخّر الله له أسبابَ الخير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بقدرةِ الله وفضلِه، وسؤالُه تسخيرَ أسبابِ الخير."},"action":{"text":"اعلم أنّ الله أجاب دعاءَ سليمانَ فسخّر له الريحَ تجري بأمره ليّنةً طيّعةً حيث أراد وقصد، تحمله ومُلكه «فسخرنا له الريح تجري بأمره رخاء حيث أصاب»؛ فهذا من تمامِ فضلِ الله على سليمانَ وإجابةِ دعائه؛ فاعلم أنّ الله يسخّر لعباده ما يشاء من مخلوقاتِه بفضله وقدرته؛ فالريحُ العاصفةُ القويّةُ تنقاد لأمرِ الله ليّنةً طيّعةً لعبده سليمان؛ فما أعظمَ قدرةَ الله وفضله؛ فاسأل الله من فضله، وثق بقدرتِه على كلِّ شيء؛ فهو القادرُ على أن يسخّر لك أسبابَ الخيرِ والتيسير؛ فمن أخلص لله وأناب إليه وتوكّل عليه سخّر الله له من الأسبابِ ما يعينه؛ فلا تيأس من فضلِ الله وتيسيره؛ واطلب منه أن ييسّر أمورك ويسخّر لك أسبابَ الخير؛ فبيدِ الله ملكوتُ كلِّ شيء؛ فاعتمد عليه، واطلب فضله، وأحسن الظنَّ بقدرته وكرمه؛ فمن توكّل على الله كفاه وسخّر له ما ينفعه."}},{"n":37,"reflection":{"text":"«والشياطين كل بناء وغواص» — وسخّرنا له الشياطينَ يعملون له، منهم البنّاؤون للأبنيةِ العظيمة، والغوّاصون في البحرِ يستخرجون اللآلئ؛ ففي هذا تمامُ التسخيرِ وعظمةُ قدرةِ الله؛ فاعلم أنّ الله على كلِّ شيءٍ قدير، يسخّر أعتى المخلوقاتِ لمن يشاء، فعظّم قدرةَ الله، وثق بأنه القادرُ على تسخيرِ كلِّ شيءٍ لعبده المؤمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ قدرةِ الله الذي يسخّر أعتى المخلوقات."},"action":{"text":"اعلم أنّ الله سخّر لسليمانَ الشياطينَ يعملون له بأمره: منهم البنّاؤون الذين يبنون له الأبنيةَ العظيمةَ والمحاريبَ والتماثيل، والغوّاصون في أعماقِ البحارِ يستخرجون له اللآلئ والجواهر «والشياطين كل بناء وغواص»؛ ففي هذا تمامُ التسخيرِ وعظمةُ قدرةِ الله؛ فالشياطينُ المتمرّدةُ العاتيةُ تنقاد لأمرِ الله وتعمل لعبدِه سليمان؛ فاعلم أنّ الله على كلِّ شيءٍ قدير، يسخّر أعتى المخلوقاتِ وأقواها لمن يشاء من عباده؛ فمن كان له مثلُ هذا المُلكِ العظيمِ وسخّرت له الشياطينُ والريحُ، فهو دليلٌ على عظمةِ قدرةِ الله ومُلكه؛ فعظّم قدرةَ الله في قلبك؛ وثق بأنه القادرُ على تسخيرِ كلِّ شيءٍ لعبدِه المؤمن؛ فلا تخف من الشياطينِ وشرورها ما دمت معتصمًا بالله؛ فالله قاهرٌ فوق عباده، مسخّرٌ لهم بأمره؛ فالجأ إلى الله القادرِ على كلِّ شيء؛ واستعذ به من شرِّ الشياطين؛ فمن اعتصم بالله عصمه، وسخّر له الأسباب، وكفاه شرَّ كلِّ ذي شر."}},{"n":38,"reflection":{"text":"«وآخرين مقرنين في الأصفاد» — وآخرين من الشياطينِ المردةِ مقيّدين في القيودِ والأغلال (كفًّا لشرّهم)؛ ففي هذا كمالُ تسخيرِ الله لسليمان؛ فاعلم أنّ الله يكفّ شرَّ المفسدين بقدرته، فاستعذ بالله من شرِّ كلِّ ذي شر، فمن استعاذ بالله كفاه شرَّ الأشرارِ وقيّد عنه أذاهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعاذةُ بالله من شرِّ الأشرار، فهو الكافُّ لشرّهم."},"action":{"text":"اعلم أنّ الله من تمامِ تسخيرِه لسليمانَ قيّد له آخرين من الشياطينِ المردةِ المفسدين في القيودِ والأغلال، كفًّا لشرّهم عن الناس «وآخرين مقرنين في الأصفاد»؛ فمن أطاعه من الشياطينِ استعمله، ومن تمرّد وأفسد قيّده وكفّ شرّه؛ ففي هذا كمالُ قدرةِ الله وتسخيرِه؛ فاعلم أنّ الله قادرٌ على أن يكفّ شرَّ المفسدين والأشرارِ بقدرته، ويقيّد عن عباده أذاهم؛ فالجأ إلى الله واستعذ به من شرِّ كلِّ ذي شر؛ فأعوذ بكلماتِ الله التامّاتِ من شرِّ ما خلق؛ فمن استعاذ بالله بصدقٍ كفاه شرَّ الأشرارِ والشياطين؛ فالله هو الحافظُ الكافي الذي يقيّد شرَّ المؤذين عن عباده المتوكّلين عليه؛ فلا تخف من شرِّ الأشرارِ ما دمت معتصمًا بالله؛ فأكثر من الأذكارِ والتعوّذاتِ الشرعية؛ فبها تُحفَظ من شرِّ الشياطينِ والأشرار؛ فمن كان الله حافظه لم يضرّه أحد؛ فاعتصم بالله، واستعذ به، وثق بحفظه وكفايته."}},{"n":39,"reflection":{"text":"«هذا عطاؤنا فامنن أو أمسك بغير حساب» — هذا عطاؤنا لك يا سليمانُ، فأعطِ من شئت وامنع من شئت، لا حسابَ عليك فيه؛ ففي هذا تفويضُ الله لسليمانَ في العطاءِ من فضله؛ فاعلم أنّ ما آتاك الله فضلٌ منه، فأنفقه في الخيرِ بسخاء، فمن أعطاه الله فليعطِ، والعطاءُ في سبيلِ الله لا ينقص المال، بل يبارك فيه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ من فضلِ الله بسخاء، وإدراكُ أنه عطاءٌ منه."},"action":{"text":"اعلم أنّ الله فوّض سليمانَ في مُلكِه وعطائه، فقال له: هذا عطاؤنا وفضلنا عليك، فأعطِ من شئت وامنع من شئت، لا حسابَ عليك ولا تبعة، فأنت مؤيّدٌ مسدّد «هذا عطاؤنا فامنن أو أمسك بغير حساب»؛ ففي هذا بيانُ أنّ ما آتاه الله سليمانَ فضلٌ ومنّةٌ منه؛ فاعلم أنّ ما آتاك الله من مالٍ أو جاهٍ أو قوّةٍ فضلٌ منه ونعمة؛ فأنفقه في وجوهِ الخيرِ والبرِّ بسخاءٍ وطيبِ نفس؛ فمن وسّع الله عليه فليوسّع على عباده؛ وأنفقوا ممّا رزقناكم؛ فالعطاءُ في سبيلِ الله لا ينقص المال، بل يبارك فيه ويزيده؛ ما نقصت صدقةٌ من مال؛ فأعطِ المحتاجين، وصِل الأرحام، وأنفق في وجوهِ الخير؛ واعلم أنّ ما تنفقه يُخلِفه الله ويضاعفه؛ فكن سخيًّا كريمًا بما آتاك الله؛ فالسخيُّ قريبٌ من الله ومن الناسِ ومن الجنّة؛ فاجعل مالك وسيلةً للقربِ من الله بالإنفاقِ والبذل؛ فما عند الله خيرٌ وأبقى؛ فأنفق ممّا آتاك الله، ولا تخش من ذي العرشِ إقلالًا."}},{"n":40,"reflection":{"text":"«وإن له عندنا لزلفى وحسن مآب» — وإنّ لسليمانَ عندنا لقربةً ومنزلةً رفيعةً وحسنَ مرجع؛ ففي هذا بيانُ منزلةِ سليمانَ عند الله مع مُلكه العظيم؛ فاعلم أنّ المُلكَ والمالَ لا يبعدان عن الله إذا صحبهما الإيمانُ والأوبة، فاجعل ما آتاك الله وسيلةً للقربِ منه، فالغنيُّ الشاكرُ الأوّابُ له عند الله زلفى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ نعمِ الدنيا وسيلةً للقربِ من الله بالشكرِ والأوبة."},"action":{"text":"اعلم أنّ الله بيّن أنّ لسليمانَ — مع مُلكِه العظيمِ الذي لا ينبغي لأحدٍ من بعده — عنده قربةً ومنزلةً رفيعةً وحسنَ مرجعٍ ومآب «وإن له عندنا لزلفى وحسن مآب»؛ ففي هذا أنّ المُلكَ والمالَ والنعمَ لا تبعد صاحبها عن الله إذا صحبها الإيمانُ والشكرُ والأوبةُ إليه؛ فسليمانُ آتاه الله مُلكًا عظيمًا، ومع ذلك كان أوّابًا شاكرًا قريبًا من الله؛ فاعلم أنّ الغنى والمُلكَ ليسا مانعينِ من القربِ من الله إذا استُعمِلا في طاعته وشُكِرت نعمتهما؛ فاجعل ما آتاك الله من نعمٍ وسيلةً للقربِ منه، لا سببًا للبعدِ عنه؛ فاشكر النعمَ، واستعملها في طاعةِ الله، وكن أوّابًا رجّاعًا إليه؛ فالغنيُّ الشاكرُ الأوّابُ له عند الله زلفى ومنزلةٌ رفيعة؛ فلا تجعل نعمَ الدنيا تشغلك عن الله؛ بل اجعلها معينةً لك على طاعته وقربه؛ فمن شكر النعمةَ وأدّى حقّها واستعملها في طاعةِ الله قرّبته إلى الله ورفعت منزلته؛ فاجمع بين نعمةِ الدنيا وحسنِ استعمالها، تنل زلفى الله وحسنَ مآبه."}},{"n":41,"reflection":{"text":"«واذكر عبدنا أيوب إذ نادى ربه أني مسني الشيطان بنصب وعذاب» — واذكر عبدنا أيوبَ حين نادى ربه: إنّ الشيطانَ مسّني بتعبٍ وألمٍ ومشقّة (في بدنه وأهلِه ومالِه)؛ ففي هذا التأسّي بصبرِ أيوبَ ولجوئه إلى الله في البلاء؛ فإذا نزل بك بلاءٌ فالجأ إلى الله واشكُ إليه، فأيوبُ شكا إلى الله لا إلى الخلق، فاجعل شكواك إلى الله وحده، فهو كاشفُ الضرّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله والشكوى إليه وحده عند البلاء."},"action":{"text":"اعلم أنّ الله أمر نبيَّه أن يتذكّر عبدَه أيوبَ حين ابتلاه في بدنه وأهلِه ومالِه، فنادى ربه شاكيًا إليه: إنّ الشيطانَ مسّني بتعبٍ وألمٍ ومشقّةٍ وعذاب «واذكر عبدنا أيوب إذ نادى ربه أني مسني الشيطان بنصب وعذاب»؛ فتأمّل كيف لجأ أيوبُ إلى الله وشكا إليه بلاءه، مع صبرِه الجميل؛ ففي هذا التأسّي بصبرِ أيوبَ ولجوئه إلى الله في البلاء؛ فإذا نزل بك بلاءٌ — مرضٌ أو فقدٌ أو ضيق — فالجأ إلى الله واشكُ حالك إليه وحده؛ فأيوبُ شكا إلى الله لا إلى الخلق، وسمّاه الله صابرًا مع شكواه إليه؛ فالشكوى إلى الله لا تنافي الصبر؛ فاجعل شكواك وبثّك وحزنك إلى الله وحده؛ إنما أشكو بثّي وحزني إلى الله؛ فهو وحده كاشفُ الضرِّ والبلاء؛ فلا تشكُ الله إلى خلقه؛ بل اشكُ إلى الله، وألحّ عليه بالدعاء، واصبر محتسبًا؛ فمن لجأ إلى الله في بلائه كشفه عنه؛ فاجعل الله ملجأك وحده عند الشدائد؛ فبالدعاءِ والصبرِ يُكشَف البلاء."}},{"n":42,"reflection":{"text":"«اركض برجلك هذا مغتسل بارد وشراب» — قلنا له: اضرب الأرضَ برجلك، فنبعت عينٌ، هذا ماءٌ باردٌ تغتسل به وتشرب منه فيُشفى بدنك؛ ففي هذا سرعةُ فرجِ الله بعد الصبرِ والدعاء؛ فاعلم أنّ فرجَ الله يأتي بأسبابٍ يسيرة، فاصبر وادعُ، فبعد الضيقِ فرج، ومن صبر على البلاءِ ودعا كشفه الله عنه بأيسرِ الأسباب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في فرجِ الله بعد الصبرِ والدعاء، ولو بأيسرِ سبب."},"action":{"text":"تأمّل كيف فرّج الله عن أيوبَ بعد صبره ودعائه: أمره أن يضرب الأرضَ برجله، فنبعت له عينُ ماءٍ باردٍ يغتسل بها فيبرأ ظاهرُ بدنه، ويشرب منها فيبرأ باطنه «اركض برجلك هذا مغتسل بارد وشراب»؛ ففي هذا سرعةُ فرجِ الله بعد الصبرِ والدعاء، وأنه يأتي بأسبابٍ يسيرةٍ سهلة؛ فاعلم أنّ فرجَ الله قريب، يأتي بأيسرِ الأسبابِ وأهونها؛ فبعد الضيقِ فرج، وبعد العسرِ يسر؛ فاصبر على البلاءِ، وألحّ على الله بالدعاء؛ فمن صبر على بلائه ودعا ربه كشفه الله عنه في أحسنِ وقتٍ وبأيسرِ سبب؛ فلا تيأس من فرجِ الله ولو طال البلاء؛ فإنّ مع العسرِ يسرًا؛ فأحسن الظنَّ بالله، وانتظر فرجه؛ فقد يأتي الفرجُ من حيث لا تحتسب، وبسببٍ لا تتوقّعه؛ فما على العبدِ إلا الصبرُ والدعاءُ وحسنُ الظنِّ بالله، والله يتولّى الفرجَ بحكمته ورحمته؛ فاصبر وادعُ وارجُ، فإنّ فرجَ الله آتٍ لا محالة؛ فمن لزم الصبرَ والدعاءَ رأى فرجَ الله ولطفه."}},{"n":43,"reflection":{"text":"«ووهبنا له أهله ومثلهم معهم رحمة منا وذكرى لأولي الألباب» — ووهبنا لأيوبَ أهله الذين فقدهم ومثلهم معهم، رحمةً منا وعبرةً لأصحابِ العقول؛ ففي هذا تعويضُ الله للصابرين بأحسنَ ممّا فقدوا؛ فاعلم أنّ الله يعوّض الصابرين خيرًا ممّا فقدوا، فاصبر على المصائبِ راجيًا عوضَ الله، فمن صبر واحتسب عوّضه الله وزاده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على المصائبِ رجاءَ عوضِ الله وزيادتِه."},"action":{"text":"اعلم أنّ الله عوّض أيوبَ بعد صبره على البلاء، فوهب له أهله الذين فقدهم ومثلهم معهم زيادةً، رحمةً منه وعبرةً لأصحابِ العقولِ السليمة «ووهبنا له أهله ومثلهم معهم رحمة منا وذكرى لأولي الألباب»؛ ففي هذا أنّ الله يعوّض الصابرين المحتسبين بأحسنَ ممّا فقدوا وأكثر؛ فاعلم أنّ من صبر على المصيبةِ واحتسب عوّضه الله خيرًا منها؛ فما ترك عبدٌ شيئًا لله أو صبر على فقدِ محبوبٍ إلا عوّضه الله خيرًا؛ فاصبر على المصائبِ والفقدِ راجيًا عوضَ الله وثوابه؛ ولا تجزع ولا تسخط؛ فإنّ الجزعَ لا يردّ المصيبةَ ويحبط الأجر؛ بل الصبرُ يجلب العوضَ والثواب؛ فمن صبر واحتسب عند المصيبةِ أخلف الله له خيرًا منها؛ فاجعل شعارك عند المصائب: إنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي وأخلف لي خيرًا منها؛ فمن قالها صادقًا أخلف الله له؛ فالصبرُ على البلاءِ سبيلُ العوضِ والثواب؛ فاصبر، واحتسب، وارجُ عوضَ الله؛ فإنه لا يضيع أجرَ الصابرين، بل يوفّيهم أجرهم بغيرِ حساب."}},{"n":44,"reflection":{"text":"«وخذ بيدك ضغثا فاضرب به ولا تحنث إنا وجدناه صابرا نعم العبد إنه أواب» — وقلنا لأيوب: خذ حزمةً من عيدانٍ فاضرب بها (زوجتك برًّا بيمينك) ولا تحنث في قسمك؛ إنا وجدنا أيوبَ صابرًا، نِعم العبدُ، إنه أوّاب؛ ففي هذا تيسيرُ الله على عبده في برِّ يمينه، وثناؤه على صبرِ أيوب؛ فاصبر على البلاءِ كأيوب، وبرَّ بيمينك، واطلب المخارجَ الشرعيةَ عند الحرج، فالصبرُ خُلُقُ الأوّابين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على البلاءِ كأيوب، والبرُّ باليمين، وطلبُ المخارجِ الشرعية."},"action":{"text":"تأمّل ختامَ قصّةِ أيوب: كان قد حلف في مرضه ليضربنّ زوجته عددًا (لأمرٍ غاضبته)، فلمّا شفاه الله رفق به وبها، فأمره أن يأخذ حزمةً من عيدانٍ فيضربها بها ضربةً واحدةً برًّا بيمينه ولا يحنث «وخذ بيدك ضغثا فاضرب به ولا تحنث إنا وجدناه صابرا نعم العبد إنه أواب»؛ ثم أثنى الله عليه: إنا وجدناه صابرًا، نِعم العبد، إنه أوّابٌ رجّاعٌ إلى الله؛ ففي هذا تيسيرُ الله على عبده مخرجًا شرعيًّا يبرّ به يمينه من غيرِ حرج، وثناؤه على صبرِ أيوب؛ فتعلّم من أيوبَ الصبرَ على البلاءِ حتى أثنى الله عليه بالصبر؛ فاصبر على بلائك كما صبر أيوب؛ وبرَّ بيمينك ووفِّ بعهدك؛ واطلب المخارجَ الشرعيةَ عند الحرجِ والضيق؛ فإنّ الله جعل مع العسرِ يسرًا، وشرع لعباده المخارجَ من الحرج؛ ومن يتّق الله يجعل له مخرجًا؛ فالصبرُ خُلُقُ الأوّابين، وثناءُ الله على أيوبَ بالصبرِ والأوبةِ يدلّ على فضلهما؛ فكن صابرًا أوّابًا، تنل ثناءَ الله ومحبّته؛ فنِعم العبدُ الصابرُ الأوّابُ إلى ربه."}}]},{"title":"الأنبياءُ المصطفون الأخيار، أولو الأيدي والأبصار","range":[45,48],"theme":"ذكرُ إبراهيمَ وإسحاقَ ويعقوبَ أصحابِ القوّةِ في العبادةِ والبصيرةِ في الدين، وأنّ الله أخلصهم بخصلةِ ذكرى الدارِ الآخرة، وأنهم من المصطفين الأخيار، ثم ذكرُ إسماعيلَ واليسعَ وذي الكفلِ وكلُّهم من الأخيار","verses":[{"n":45,"reflection":{"text":"«واذكر عبادنا إبراهيم وإسحاق ويعقوب أولي الأيدي والأبصار» — واذكر عبادنا إبراهيمَ وإسحاقَ ويعقوبَ أصحابَ القوّةِ في العبادةِ والبصائرِ في الدين؛ ففي هذا مدحُ الأنبياءِ بالقوّةِ في الطاعةِ والبصيرةِ في الحق؛ فاجمع بين قوّةِ العملِ وبصيرةِ العلم، فالعبادةُ بلا علمٍ ضلال، والعلمُ بلا عملٍ وبال، فكن ذا يدٍ في العملِ وبصرٍ في الدين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين قوّةِ العملِ وبصيرةِ العلمِ في الدين."},"action":{"text":"اعلم أنّ الله أمر نبيَّه أن يتذكّر عبادَه إبراهيمَ وإسحاقَ ويعقوبَ، ووصفهم بأنهم أولو الأيدي والأبصار — أي أصحابُ القوّةِ في العبادةِ والطاعة، والبصائرِ النافذةِ في دينِ الله «واذكر عبادنا إبراهيم وإسحاق ويعقوب أولي الأيدي والأبصار»؛ فجمعوا بين قوّةِ العملِ وبصيرةِ العلم؛ فاجمع أنت بين قوّةِ العملِ والاجتهادِ في الطاعة، وبصيرةِ العلمِ والفقهِ في الدين؛ فالعبادةُ بلا علمٍ وبصيرةٍ ضلالٌ وابتداع، والعلمُ بلا عملٍ حجّةٌ ووبال؛ فكن ذا يدٍ قويّةٍ في العملِ الصالح، وذا بصرٍ نافذٍ في فهمِ الدين؛ فاطلب العلمَ النافع، واعمل به؛ فقيمةُ العلمِ في العمل، وقيمةُ العملِ في موافقتِه للعلمِ والسنّة؛ فاقتدِ بالأنبياءِ في الجمعِ بين القوّةِ والبصيرة؛ فمن جمع بينهما كمُل دينه، ونفع نفسه وغيره؛ فتفقّه في دينك، وقوِّ عملك، وكن عالمًا عاملًا بصيرًا."}},{"n":46,"reflection":{"text":"«إنا أخلصناهم بخالصة ذكرى الدار» — إنا اصطفيناهم وجعلنا لهم خصلةً خالصة، وهي إكثارُهم من ذكرِ الدارِ الآخرةِ والعملِ لها؛ ففي هذا أنّ استحضارَ الآخرةِ من خصالِ المصطفين؛ فأكثر من ذكرِ الآخرةِ والعملِ لها، فاستحضارُ الدارِ الآخرةِ يزكّي القلبَ ويقوّم العمل، فمن عمّر قلبه بذكرِ الآخرةِ صلح حاله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من ذكرِ الآخرةِ والعملِ لها، فهي خصلةُ المصطفين."},"action":{"text":"اعلم أنّ الله أخبر أنه أخلص أنبياءه إبراهيمَ وإسحاقَ ويعقوبَ واصطفاهم بخصلةٍ خالصةٍ عظيمة، وهي إكثارُهم من ذكرِ الدارِ الآخرةِ والعملِ لها وإخلاصِهم فيها «إنا أخلصناهم بخالصة ذكرى الدار»؛ ففي هذا أنّ استحضارَ الآخرةِ وذكرَها والعملَ لها من خصالِ المصطفين الأخيار؛ فأكثر من ذكرِ الدارِ الآخرةِ — الموتِ وما بعده، والجنّةِ والنار، والحسابِ والجزاء — واعمل لها؛ فاستحضارُ الآخرةِ يزكّي القلب، ويقوّم العمل، ويهوّن الدنيا، ويحمل على الطاعةِ واجتنابِ المعصية؛ فمن عمّر قلبه بذكرِ الآخرةِ صلح حاله واستقام عمله؛ فاجعل الآخرةَ نصبَ عينيك في كلِّ عمل؛ ووازن أعمالك بميزانها؛ فمن كانت الآخرةُ همّه جمع الله له شمله، وجعل غناه في قلبه، وأتته الدنيا وهي راغمة؛ فأكثر من ذكرِ الموتِ هادمِ اللذات؛ واعمل لدارِ البقاءِ لا لدارِ الفناء؛ فالسعيدُ من عمّر آخرته، والخاسرُ من آثر دنياه على أخراه."}},{"n":47,"reflection":{"text":"«وإنهم عندنا لمن المصطفين الأخيار» — وإنهم عندنا لمن المختارين المصطفَين خيارِ الخلق؛ ففي هذا بيانُ منزلتهم الرفيعةِ عند الله؛ فاعلم أنّ الله يصطفي من عباده الأخيار، فاجتهد لتكون من الأخيار بالإيمانِ والعملِ الصالح، فالاصطفاءُ ثمرةُ الإخلاصِ والعملِ لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"السعيُ لتكون من الأخيار بالإيمانِ والعمل، فالاصطفاءُ ثمرتُهما."},"action":{"text":"اعلم أنّ الله شهد لأنبيائه إبراهيمَ وإسحاقَ ويعقوبَ بأنهم عنده من المصطفين المختارين، خيارِ الخلقِ وصفوتهم «وإنهم عندنا لمن المصطفين الأخيار»؛ ففي هذا بيانُ منزلتهم الرفيعةِ عند الله واصطفائه لهم؛ فاعلم أنّ الله يصطفي من عباده الأخيار، ويختار من يشاء لكرامته؛ والاصطفاءُ وإن كان محضَ فضلِ الله، فإنه يقارنه الإخلاصُ والعملُ الصالحُ والخيرية؛ فاجتهد لتكون من الأخيار الذين يحبّهم الله، بالإيمانِ الصادقِ والعملِ الصالحِ والأخلاقِ الفاضلة؛ فخيرُ الناسِ أنفعهم للناس، وأحسنهم خلقًا، وأتقاهم لله؛ فاسعَ للخيريةِ في دينك وعملك وخلقك؛ فمن أخلص لله واجتهد في طاعته وأحسن خلقه كان من الأخيار؛ فاطلب أن تكون من خيارِ عبادِ الله بالإيمانِ والتقوى والإحسان؛ فالأخيارُ هم صفوةُ الله من خلقه؛ فتشبّه بهم في خصالهم، واقتدِ بهديهم؛ فبالاقتداءِ بالأخيارِ تصير منهم؛ فاجعل همّك الخيريةَ والصلاحَ والإخلاصَ لله."}},{"n":48,"reflection":{"text":"«واذكر إسماعيل واليسع وذا الكفل وكل من الأخيار» — واذكر إسماعيلَ واليسعَ وذا الكفلِ، وكلُّهم من الأخيارِ المختارين؛ ففي هذا مدحُ هؤلاء الأنبياءِ وأنهم من الأخيار؛ فاقتدِ بالأنبياءِ الأخيارِ في صبرهم وطاعتهم، فذكرُ الأخيارِ يبعث على الاقتداءِ بهم، فاجعل سِيَرهم قدوةً لك في الخيرِ والصلاح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالأنبياءِ الأخيار، فذكرُهم يبعث على التأسّي بهم."},"action":{"text":"اعلم أنّ الله أمر نبيَّه أن يتذكّر أيضًا إسماعيلَ واليسعَ وذا الكفلِ من أنبيائه، وشهد لهم جميعًا بالخيرية فقال: وكلٌّ من الأخيارِ المختارين صفوةِ الخلق «واذكر إسماعيل واليسع وذا الكفل وكل من الأخيار»؛ ففي هذا مدحُ هؤلاء الأنبياءِ الكرامِ وبيانُ أنهم من الأخيار؛ فاقتدِ بالأنبياءِ الأخيارِ في صبرهم على البلاءِ وطاعتهم لربهم وإخلاصهم ودعوتهم؛ فذكرُ الأخيارِ وسِيَرهم يبعث القلبَ على الاقتداءِ بهم والتأسّي بهديهم؛ فاقرأ سِيَر الأنبياءِ والصالحين، وتأمّل أخلاقهم وأعمالهم، واجعلها قدوةً لك في الخيرِ والصلاح؛ فأولئك الذين هدى الله فبهداهم اقتدِه؛ فبالاقتداءِ بالأخيارِ يرتفع العبدُ ويصلح؛ فاجعل الأنبياءَ والصالحين قدوتك، لا أهلَ الفسوقِ والضلال؛ فالمرءُ على دينِ خليله، ومع من أحبّ؛ فأحبّ الأخيارَ، واقتدِ بهم، واسلك سبيلهم؛ فمن تشبّه بقومٍ فهو منهم؛ فتشبّه بالأخيار، تكن من الأخيار."}}]},{"title":"جزاءُ المتّقين: حسنُ المآبِ ونعيمُ جنّاتِ عدنٍ الدائم","range":[49,54],"theme":"أنّ القرآنَ ذكر، وأنّ للمتّقين حسنَ مآبٍ في جنّاتِ عدنٍ مفتّحةٍ لهم أبوابها، متّكئين يُؤتَون ما يشتهون من الفاكهةِ والشرابِ والأزواجِ العفيفات، وأنّ ذلك رزقُ الله الذي لا نفادَ له","verses":[{"n":49,"reflection":{"text":"«هذا ذكر وإن للمتقين لحسن مآب» — هذا القرآنُ ذكرٌ وشرف، وإنّ للمتّقين حسنَ مرجعٍ ومنقلبٍ في الآخرة؛ ففي هذا بشارةُ المتّقين بحسنِ العاقبة؛ فاتّق الله لتنال حسنَ المآب، فالتقوى سبيلُ حسنِ العاقبةِ في الآخرة، فاجعل التقوى زادك لتفوز بحسنِ المرجعِ عند الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى رجاءَ حسنِ المآبِ والعاقبةِ عند الله."},"action":{"text":"اعلم أنّ الله بيّن أنّ هذا القرآنَ ذكرٌ وشرفٌ وموعظة، ثم بشّر المتّقين بحسنِ المرجعِ والمنقلبِ في الآخرة «هذا ذكر وإن للمتقين لحسن مآب»؛ ففي هذا بشارةُ المتّقين بحسنِ العاقبةِ والمآب؛ فاتّق الله لتكون من المتّقين الذين وعدهم الله بحسنِ المآب؛ فالتقوى — بامتثالِ الأوامرِ واجتنابِ النواهي — سبيلُ حسنِ العاقبةِ في الدنيا والآخرة؛ فالعاقبةُ للتقوى؛ فاجعل التقوى زادك ولباسك وشعارك؛ واتّق الله حيثما كنت؛ فمن اتّقى الله وقاه وكفاه وجعل له مخرجًا ورزقًا وحسنَ مآب؛ فحسّن عاقبتك بالتقوى؛ فالمتّقون لهم عند ربهم جنّاتُ النعيم؛ فاعمل عملَ المتّقين لتنال جزاءهم؛ فبادر بالتقوى والعملِ الصالحِ قبل فواتِ الأوان؛ فحسنُ المآبِ لا يُنال إلا بالتقوى والعملِ الصالح؛ فاسلك سبيلَ المتّقين، تفز بحسنِ المرجعِ عند الله."}},{"n":50,"reflection":{"text":"«جنات عدن مفتحة لهم الأبواب» — ذلك المآبُ الحسنُ جنّاتُ إقامةٍ دائمةٍ أبوابها مفتّحةٌ لهم إكرامًا؛ ففي هذا وصفُ نعيمِ المتّقين وإكرامهم؛ فاعمل لجنّاتِ عدنٍ التي تُفتَّح أبوابها للمتّقين، فتصوّرُ نعيمِ الجنّةِ يبعث على العمل، فاجعل الجنّةَ غايةَ سعيك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لجنّاتِ عدن، وتصوّرُ نعيمِها الباعثُ على السعي."},"action":{"text":"اعلم أنّ الله وصف حسنَ مآبِ المتّقين بأنه جنّاتُ عدنٍ — أي جنّاتُ إقامةٍ دائمةٍ لا يظعنون عنها — مفتّحةٌ لهم أبوابها إكرامًا وترحيبًا «جنات عدن مفتحة لهم الأبواب»؛ فتُفتَّح لهم الأبوابُ ترحيبًا بهم عند قدومهم؛ ففي هذا وصفُ نعيمِ المتّقين وإكرامِ الله لهم؛ فاعمل لجنّاتِ عدنٍ التي تُفتَّح أبوابها للمتّقين المكرمين؛ فتصوّرُ نعيمِ الجنّةِ وإكرامِ أهلها يبعث القلبَ على العملِ والاجتهاد؛ فتذكّر الجنّةَ وأبوابها المفتّحةَ ونعيمها المقيم؛ فمن اشتاق إلى الجنّةِ سارع في الخيرات؛ فاجعل الجنّةَ غايةَ سعيك ومنتهى رجائك؛ واعمل عملَ أهلها من الإيمانِ والتقوى والطاعة؛ فالجنّةُ سلعةُ الله الغالية، ألا إنّ سلعةَ الله الجنّة؛ فاعمل لها، واطلبها بالإيمانِ والعملِ الصالح؛ فمن طلب الجنّةَ بصدقٍ وعملٍ نالها بإذنِ الله؛ فسارع إلى مغفرةٍ من ربك وجنّةٍ عرضها السماواتُ والأرضُ أُعدّت للمتّقين."}},{"n":51,"reflection":{"text":"«متكئين فيها يدعون فيها بفاكهة كثيرة وشراب» — متّكئين على الأرائكِ في الجنّة، يطلبون فيها ما يشتهون من فاكهةٍ كثيرةٍ وشرابٍ لذيذ؛ ففي هذا وصفُ راحةِ أهلِ الجنّةِ ونعيمهم؛ فاعمل لهذا النعيمِ المقيم، فراحةُ الجنّةِ ونعيمُها جزاءُ من تعب في طاعةِ الله، فاصبر على مشقّةِ الطاعةِ لتنال راحةَ الجنّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على مشقّةِ الطاعةِ رجاءَ راحةِ الجنّةِ ونعيمِها."},"action":{"text":"اعلم أنّ الله وصف نعيمَ أهلِ الجنّةِ فقال: هم متّكئون على الأرائكِ في راحةٍ وطمأنينة، يطلبون ما يشتهون من فاكهةٍ كثيرةٍ متنوّعةٍ وشرابٍ لذيذ، فيأتيهم ما يدعون «متكئين فيها يدعون فيها بفاكهة كثيرة وشراب»؛ ففي هذا وصفُ راحةِ أهلِ الجنّةِ وتمامِ نعيمهم وقضاءِ مطالبهم؛ فاعمل لهذا النعيمِ المقيمِ والراحةِ الدائمة؛ فراحةُ الجنّةِ ونعيمُها جزاءُ من تعب في طاعةِ الله وصبر على مشقّتها؛ فاصبر على مشقّةِ الطاعةِ وتعبِ العبادةِ في الدنيا، لتنال راحةَ الجنّةِ ونعيمها في الآخرة؛ فالدنيا دارُ عملٍ وتعب، والآخرةُ دارُ جزاءٍ وراحة؛ فمن تعب في طاعةِ الله استراح في جنّته؛ فلا تؤثر راحةَ الدنيا الفانيةَ على راحةِ الآخرةِ الباقية؛ فتعبُ ساعةٍ في الطاعةِ يعقبه نعيمٌ أبدي؛ فاصبر على الطاعة، واحتسب مشقّتها؛ فإنّ ما عند الله لا يُنال إلا بتركِ ما تشتهي النفوسُ من الراحةِ والدعة؛ فحُفّت الجنّةُ بالمكاره؛ فاصبر على المكاره، تظفر بالجنّةِ ونعيمها."}},{"n":52,"reflection":{"text":"«وعندهم قاصرات الطرف أتراب» — وعندهم أزواجٌ حابساتٌ أعينهنّ على أزواجهنّ (لا ينظرن لغيرهم)، مستوياتٌ في السنّ؛ ففي هذا تمامُ نعيمِ أهلِ الجنّة؛ فاعمل لهذا الجزاءِ الطيّب، واعلم أنّ العفّةَ في الدنيا سبيلٌ لنعيمِ الجنّة، فاحفظ نفسك عن الحرامِ لتنال الحلالَ الطيّبَ في الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ النفسِ عن الحرامِ رجاءَ الطيّباتِ في الجنّة."},"action":{"text":"اعلم أنّ الله من تمامِ وصفِ نعيمِ أهلِ الجنّةِ ذكر أنّ عندهم أزواجًا قاصراتِ الطرف — أي حابساتٍ أعينهنّ على أزواجهنّ لا يطمحن إلى غيرهم عفّةً ومحبّة — أترابًا مستوياتٍ في السنِّ والحسن «وعندهم قاصرات الطرف أتراب»؛ ففي هذا تمامُ نعيمِ أهلِ الجنّةِ من الأزواجِ الطيّباتِ العفيفات؛ فاعمل لهذا الجزاءِ الطيّبِ في جنّاتِ النعيم؛ واعلم أنّ العفّةَ وحفظَ النفسِ عن الحرامِ في الدنيا سبيلٌ لنيلِ الطيّباتِ في الجنّة؛ فالجزاءُ من جنسِ العمل؛ فمن عفّ في الدنيا عن الحرامِ نال الطيّباتِ الحلالَ في الآخرة؛ فاحفظ نفسك وبصرك وفرجك عن الحرام؛ وغُضّ بصرك عمّا حرّم الله؛ فحفظُ الفرجِ والبصرِ من صفاتِ المؤمنين المفلحين؛ والذين هم لفروجهم حافظون؛ فمن ترك شهوةً محرّمةً لله عوّضه الله خيرًا منها في الدنيا والآخرة؛ فاصبر عن الحرام، واقنع بالحلال، وارجُ الطيّباتِ في الجنّة؛ فعفّةُ ساعةٍ في الدنيا نعيمٌ مقيمٌ في الآخرة؛ فاجعل العفّةَ والطهارةَ خُلُقك؛ فبها تنال رضا الله وطيّباتِ جنّته."}},{"n":53,"reflection":{"text":"«هذا ما توعدون ليوم الحساب» — هذا النعيمُ هو ما توعدون به يومَ الحساب جزاءً على أعمالكم؛ ففي هذا تحقيقُ وعدِ الله للمتّقين؛ فاعلم أنّ وعدَ الله بالجنّةِ للمتّقين حقٌّ لا يتخلّف، فاعمل واثقًا بوعدِ الله، فمن عمل لله وثق بوعده، فوعدُ الله آتٍ لا محالة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بوعدِ الله الحقِّ للمتّقين، والعملُ رجاءَه."},"action":{"text":"اعلم أنّ الله بيّن أنّ هذا النعيمَ الموصوفَ في الجنّةِ هو ما وعد الله به المتّقين، يُوفّونه يومَ الحسابِ جزاءً على إيمانهم وأعمالهم «هذا ما توعدون ليوم الحساب»؛ ففي هذا تحقيقُ وعدِ الله للمتّقين وتأكيدُه؛ فاعلم أنّ وعدَ الله بالجنّةِ للمتّقين حقٌّ ثابتٌ لا يتخلّف ولا يُخلَف؛ فإنّ الله لا يخلف الميعاد؛ فاعمل واثقًا بوعدِ الله، مستيقنًا بجزائه؛ فمن عمل لله وأحسن الظنَّ به وثق بوعده؛ فالله وعد المتّقين والمؤمنين العاملين بالجنّةِ والنعيم، ووعده حق؛ فاطمئنّ إلى وعدِ الله، واعمل لنيلِ موعوده؛ فلا تستبطئ الجزاء، ولا تشكّ في الوعد؛ فوعدُ الله آتٍ لا محالة يومَ الحساب؛ فاجعل يقينك بوعدِ الله حافزًا للعمل؛ فمن أيقن بالجزاءِ عمل له؛ فاعمل عملَ الموقنين بلقاءِ الله ووعده؛ فإنّ ما عند الله حقٌّ لمن آمن وعمل صالحًا؛ فثق بوعدِ الله، واعمل لجنّته، وانتظر موعوده يومَ الحساب."}},{"n":54,"reflection":{"text":"«إن هذا لرزقنا ما له من نفاد» — إنّ هذا النعيمَ لرزقنا لأهلِ الجنّة، لا انقطاعَ له ولا فناء؛ ففي هذا بيانُ دوامِ نعيمِ الجنّةِ وأبديّته؛ فاعمل للنعيمِ الدائمِ الذي لا ينفد، ولا تؤثر لذّةَ الدنيا الفانيةَ على نعيمِ الآخرةِ الباقي، فالعاقلُ يؤثر الباقيَ على الفاني.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ النعيمِ الباقي على لذّةِ الدنيا الفانية."},"action":{"text":"اعلم أنّ الله ختم وصفَ نعيمِ الجنّةِ بأنه رزقٌ دائمٌ لا انقطاعَ له ولا فناءَ ولا نقص «إن هذا لرزقنا ما له من نفاد»؛ فنعيمُ الجنّةِ أبديٌّ لا ينفد، بخلافِ نعيمِ الدنيا الزائلِ المنقطع؛ ففي هذا بيانُ دوامِ نعيمِ الجنّةِ وأبديّته؛ فاعمل للنعيمِ الدائمِ الباقي الذي لا ينفد، لا للذّةِ الدنيا الفانيةِ المنقطعة؛ فما عندكم ينفد وما عند الله باق؛ فلا تؤثر لذّةَ الدنيا العاجلةَ الفانيةَ على نعيمِ الآخرةِ الآجلِ الباقي؛ فالعاقلُ يؤثر الباقيَ على الفاني، والدائمَ على المنقطع؛ بل تؤثرون الحياةَ الدنيا والآخرةُ خيرٌ وأبقى؛ فوازن بين لذّةٍ فانيةٍ ونعيمٍ باقٍ، فأيّهما أحقّ بالإيثار؟ فمن آثر الفانيَ على الباقي فقد غُبِن؛ فاعمل لدارِ البقاءِ ونعيمها الدائم؛ ولا تبع الباقيَ بالفاني؛ فالدنيا كلُّها متاعُ الغرور، والآخرةُ هي دارُ القرارِ والنعيمِ المقيم؛ فاجعل سعيك للنعيمِ الذي لا ينفد؛ فمن عمل للباقي ربح، ومن عمل للفاني خسر."}}]},{"title":"جزاءُ الطاغين: شرُّ المآبِ وجهنمُ وتخاصمُ أهلِها","range":[55,64],"theme":"أنّ للطاغين شرَّ مآبٍ في جهنمَ يصلَونها ويذوقون الحميمَ والغسّاقَ وأصنافَ العذاب، وتخاصمُ أهلِ النارِ وتبرّؤُ المتبوعين من التابعين وتلاعنهم ودعاءُ بعضهم على بعض، وتفقّدُهم للمؤمنين الذين كانوا يحتقرونهم فإذا هم في الجنّة، وأنّ ذلك التخاصمَ حقٌّ واقع","verses":[{"n":55,"reflection":{"text":"«هذا وإن للطاغين لشر مآب» — هذا جزاءُ المتّقين، وإنّ للطاغين المتجاوزين حدودَ الله لشرَّ مرجعٍ ومنقلب؛ ففي هذا مقابلةُ جزاءِ المتّقين بجزاءِ الطاغين؛ فاحذر الطغيانَ ومجاوزةَ حدودِ الله، فإنّ عاقبتَه شرُّ مآب، فالزم حدودَ الله ولا تتجاوزها، فالطغيانُ سبيلُ الهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الطغيانِ ومجاوزةِ حدودِ الله، ولزومُ حدودِه."},"action":{"text":"اعلم أنّ الله بعد أن ذكر جزاءَ المتّقين وحسنَ مآبهم، قابله بجزاءِ الطاغين، فقال: هذا للمتّقين، وإنّ للطاغين المتجاوزين حدودَ الله المتمرّدين على أمره لشرَّ مرجعٍ ومنقلبٍ ومآب «هذا وإن للطاغين لشر مآب»؛ ففي هذا مقابلةُ جزاءِ الفريقين ليختار العبدُ لنفسه؛ فاحذر الطغيانَ ومجاوزةَ حدودِ الله، فإنّ عاقبتَه شرُّ المآبِ والعذابُ الأليم؛ فالطغيانُ مجاوزةُ الحدِّ في الكفرِ والظلمِ والمعاصي؛ فالزم حدودَ الله، ولا تتجاوزها؛ تلك حدودُ الله فلا تعتدوها؛ فمن التزم حدودَ الله نجا، ومن تجاوزها وطغى هلك؛ فراقب نفسك ألا تطغى وتتجاوز؛ فإنّ النفسَ أمّارةٌ بالسوء، ميّالةٌ إلى الطغيان؛ كلا إنّ الإنسانَ ليطغى أن رآه استغنى؛ فاكبح جماحَ نفسك عن الطغيان؛ والزم أمرَ الله ونهيه؛ فالتقوى والالتزامُ بحدودِ الله سبيلُ النجاة، والطغيانُ ومجاوزتها سبيلُ الهلاك؛ فاختر لنفسك سبيلَ المتّقين لا سبيلَ الطاغين؛ فالعاقبةُ للمتّقين، وشرُّ المآبِ للطاغين."}},{"n":56,"reflection":{"text":"«جهنم يصلونها فبئس المهاد» — ذلك المآبُ جهنمُ يدخلونها ويقاسون حرّها، فبئس الفراشُ والمستقرّ؛ ففي هذا بيانُ سوءِ مصيرِ الطاغين؛ فاحذر النارَ التي هي مصيرُ الطاغين، فتذكّرُ النارِ يردع عن المعاصي، فاجعل خوفَ النارِ حاجزًا بينك وبين ما يوصلك إليها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من النار، وجعلُ خوفِها حاجزًا عن المعاصي."},"action":{"text":"اعلم أنّ الله بيّن أنّ شرَّ مآبِ الطاغين هو جهنمُ، يدخلونها ويصلَون حرّها وعذابها، فبئس الفراشُ والمستقرُّ والمهادُ لهم «جهنم يصلونها فبئس المهاد»؛ ففي هذا بيانُ سوءِ مصيرِ الطاغين وقبحِ منقلبهم؛ فاحذر النارَ التي هي مصيرُ الطاغين والمتجاوزين حدودَ الله؛ فتذكّرُ النارِ وعذابها يردع عن المعاصي والطغيان؛ فاجعل خوفَ النارِ حاجزًا بينك وبين كلِّ ما يوصلك إليها من الكفرِ والمعاصي؛ فاتّقوا النارَ التي وقودها الناسُ والحجارة؛ فمن خاف النارَ اجتنب أسبابها؛ فتصوّر عذابَ النارِ وبئسَ مهادها، ليحملك ذلك على التقوى واجتنابِ المعاصي؛ فالنارُ دركاتٌ وعذابها أليم؛ فاستعذ بالله منها، واعمل عملًا يباعدك عنها؛ فمن سأل الله الجنّةَ ثلاثًا قالت الجنّةُ اللهم أدخله الجنّة، ومن استجار من النارِ ثلاثًا قالت النارُ اللهم أجره منها؛ فأكثر من الاستعاذةِ من النار، واجتنب ما يوصل إليها؛ فخوفُ النارِ سائقٌ إلى الطاعة، زاجرٌ عن المعصية؛ فاجعله حاجزًا لك عن كلِّ حرام."}},{"n":57,"reflection":{"text":"«هذا فليذوقوه حميم وغساق» — هذا العذابُ فليذوقوه، ماءٌ حارٌّ بلغ منتهى الحرارة، وصديدٌ باردٌ منتنٌ من أهلِ النار؛ ففي هذا تصويرُ شرابِ أهلِ النارِ وشدّةِ عذابهم؛ فاحذر ما يوصلك إلى هذا العذاب، واعمل لتنجو منه، فتصوّرُ عذابِ النارِ يحمل على التوبةِ والعمل، فبادر بالطاعةِ قبل ذوقِ العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النار، والمبادرةُ بالطاعةِ والتوبة."},"action":{"text":"اعلم أنّ الله صوّر شرابَ أهلِ النارِ وعذابهم فقال: هذا العذابُ فليذوقوه، منه حميمٌ — وهو الماءُ الحارُّ الذي بلغ منتهى الغليانِ والحرارة يقطّع أمعاءهم — وغسّاقٌ — وهو الصديدُ الباردُ المنتنُ السائلُ من جلودِ أهلِ النار «هذا فليذوقوه حميم وغساق»؛ ففي هذا تصويرُ شدّةِ عذابِ أهلِ النارِ وقبحِ شرابهم؛ فاحذر ما يوصلك إلى هذا العذابِ الأليمِ من الكفرِ والطغيانِ والمعاصي؛ واعمل لتنجو منه بالإيمانِ والتقوى والعملِ الصالح؛ فتصوّرُ عذابِ النارِ وشرابها المهينِ يحمل القلبَ على التوبةِ والإنابةِ والعمل؛ فمن تذكّر الحميمَ والغسّاقَ هان عليه تركُ الشهواتِ المحرّمة؛ فبادر بالطاعةِ والتوبةِ قبل أن تذوق العذاب؛ فإنّ من ذاق عذابَ النارِ تمنّى الرجوعَ ليعمل صالحًا فلا يُجاب؛ فاعمل في زمنِ المهلةِ لتنجو من عذابِ الآخرة؛ فالكيّسُ من عمل لما بعد الموت؛ فاجعل تذكّرَ عذابِ النارِ دافعًا لك إلى الطاعةِ وزاجرًا عن المعصية؛ فمن خاف أدلج، ومن أدلج بلغ المنزل؛ فبادر بالعملِ الصالحِ قبل فواتِ الأوان."}},{"n":58,"reflection":{"text":"«وآخر من شكله أزواج» — ولهم أنواعٌ أخرى من العذابِ من جنسِ هذا، أصنافٌ متعدّدة؛ ففي هذا بيانُ تنوّعِ عذابِ أهلِ النار؛ فاعلم أنّ عذابَ النارِ ألوانٌ وأصناف، فاحذر أسبابَ العذابِ كلَّها، واعمل لتنجو من ألوانِ العذاب، فمن اتّقى الله نجّاه من كلِّ عذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أسبابِ العذابِ كلِّها، والعملُ للنجاةِ منها."},"action":{"text":"اعلم أنّ الله بيّن أنّ لأهلِ النارِ ألوانًا أخرى من العذابِ من جنسِ الحميمِ والغسّاق، أصنافًا متعدّدةً وأزواجًا متنوّعة «وآخر من شكله أزواج»؛ ففي هذا بيانُ تنوّعِ عذابِ أهلِ النارِ وتعدّدِ ألوانه وأصنافه؛ فاعلم أنّ عذابَ النارِ ألوانٌ وأصنافٌ وأنواعٌ لا تُحصى، كلُّها أليمةٌ شديدة؛ فاحذر أسبابَ العذابِ كلَّها من الكفرِ والشركِ والمعاصي والظلم؛ واعمل لتنجو من ألوانِ العذابِ وأصنافه؛ فمن اتّقى الله واجتنب أسبابَ سخطه نجّاه من كلِّ عذاب؛ فاجعل التقوى حصنك من ألوانِ العذاب؛ فكما تنوّعت أصنافُ العذابِ للطاغين، تنوّعت أسبابُها من المعاصي؛ فاجتنب المعاصيَ كلَّها صغيرها وكبيرها؛ فرُبّ صغيرةٍ جرّت إلى كبيرة، ورُبّ معصيةٍ أوردت النار؛ فاحذر جميعَ أسبابِ العذاب؛ واعمل بجميعِ أسبابِ النجاةِ من الإيمانِ والتقوى والطاعةِ والتوبة؛ فمن جانب أسبابَ العذابِ ولزم أسبابَ النجاةِ فاز؛ فاطلب النجاةَ من النارِ بألوانها، بالتقوى والعملِ الصالحِ والتوبةِ النصوح."}},{"n":59,"reflection":{"text":"«هذا فوج مقتحم معكم لا مرحبا بهم إنهم صالو النار» — يُقال لرؤساءِ الضلالِ حين يدخل أتباعهم: هذا فوجٌ داخلٌ معكم النار، لا ترحيبَ بهم، إنهم داخلو النار؛ ففي هذا تبرّؤُ المتبوعين من التابعين في النار؛ فاحذر أن تتبع أهلَ الضلالِ فيتبرّؤوا منك يومَ القيامة، فلا تنفعك التبعيةُ في الباطل، فاتّبع الحقَّ وحده لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ أهلِ الضلال، فيتبرّؤون يومَ القيامة."},"action":{"text":"تأمّل مشهدَ تخاصمِ أهلِ النار: يُقال لرؤساءِ الضلالِ حين يدخل أتباعهم معهم النار: هذا فوجٌ من أتباعكم داخلٌ معكم مقتحمٌ النار، فيقول الرؤساءُ متبرّئين: لا ترحيبَ بهم ولا سعةَ عليهم، إنهم داخلو النارِ وصالوها كما دخلناها «هذا فوج مقتحم معكم لا مرحبا بهم إنهم صالو النار»؛ ففي هذا تبرّؤُ المتبوعين من التابعين في النار، وتلاعنهم؛ فاحذر أن تتبع أهلَ الضلالِ والباطلِ في ضلالهم، فيتبرّؤوا منك يومَ القيامةِ حين لا ينفع الندم؛ فإنّ التبعيةَ في الباطلِ لا تنفع، بل ينقلب الأخلّاءُ يومئذٍ بعضهم لبعضٍ عدوًّا إلا المتّقين؛ فلا تتّبع في دينك إلا الحقَّ والدليل، لا الرجالَ والجموع؛ فمن اتّبع أهلَ الباطلِ تبرّؤوا منه يومَ القيامة، وتلاعنوا، وتبرّأ بعضهم من بعض؛ فاتّبع الحقَّ وحده، واجعل قدوتك الأنبياءَ والصالحين لا أئمّةَ الضلال؛ فالنجاةُ في اتّباعِ الحقِّ، لا في تقليدِ الرجالِ على الباطل؛ فتبرّأ من الباطلِ وأهله في الدنيا، قبل أن يتبرّؤوا منك في الآخرة."}},{"n":60,"reflection":{"text":"«قالوا بل أنتم لا مرحبا بكم أنتم قدمتموه لنا فبئس القرار» — قال التابعون للرؤساء: بل أنتم لا ترحيبَ بكم، أنتم قدّمتم لنا هذا العذابَ بإضلالكم، فبئس المستقرُّ جهنم؛ ففي هذا تلاومُ أهلِ النارِ وتبادلُ اللعن؛ فاحذر أن تُضِلَّ غيرك أو تُضَلَّ، فالمُضِلُّ والمُضَلُّ كلاهما في النارِ يتلاعنان، فاحرص على هدايةِ نفسك وغيرك لتنجو من هذا التلاوم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإضلالِ والضلال، فعاقبتُهما التلاومُ في النار."},"action":{"text":"تأمّل ردَّ التابعين على رؤسائهم في النار: قالوا بل أنتم لا ترحيبَ بكم ولا سعةَ عليكم، فأنتم الذين قدّمتم لنا هذا العذابَ بإضلالكم إيّانا وصدّكم لنا عن الحق، فبئس المستقرُّ والقرارُ جهنم «قالوا بل أنتم لا مرحبا بكم أنتم قدمتموه لنا فبئس القرار»؛ ففي هذا تلاومُ أهلِ النارِ وتبادلهم اللعنَ والتوبيخ؛ فيلوم التابعون متبوعيهم على إضلالهم؛ فاحذر أن تكون مُضِلًّا لغيرك بدعوتك إلى باطلٍ أو تزيينِ معصية؛ واحذر أن تكون مُضَلًّا تتبع أهلَ الباطل؛ فالمُضِلُّ والمُضَلُّ كلاهما في النارِ يتلاعنان ويتلاومان؛ فمن سنّ سنّةً سيّئةً فعليه وزرها ووزرُ من عمل بها؛ فاحرص على هدايةِ نفسك أولًا، ثم هدايةِ غيرك إلى الحق؛ فادعُ إلى الخير، ولا تدعُ إلى شر؛ فالداعي إلى الهدى له مثلُ أجورِ من تبعه، والداعي إلى الضلالةِ عليه مثلُ أوزارِ من تبعه؛ فكن هاديًا لا مُضِلًّا، ومهتديًا لا ضالًّا؛ فبذلك تنجو من تلاومِ أهلِ النارِ وتلاعنهم؛ فالنجاةُ في الهدايةِ والدعوةِ إلى الحق."}},{"n":61,"reflection":{"text":"«قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا في النار» — قال الأتباع: ربّنا من أضلّنا وقدّم لنا هذا العذابَ فضاعف له العذابَ في النار؛ ففي هذا دعاءُ الأتباعِ على المتبوعين المُضِلّين؛ فاحذر أن تكون سببًا في ضلالِ غيرك فيدعو عليك ويضاعَف عذابك، فادعُ إلى الخيرِ لا إلى الشر، فالمُضِلُّ يحمل وزره ووزرَ من أضلّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التسبّبِ في ضلالِ الغير، والدعوةُ إلى الخير."},"action":{"text":"تأمّل دعاءَ الأتباعِ على رؤسائهم المُضِلّين في النار: قالوا ربّنا من أضلّنا وسنّ لنا هذا الضلالَ وقدّم لنا سببَ هذا العذابِ فضاعف له العذابَ في النارِ جزاءَ إضلالِه لنا «قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا في النار»؛ ففي هذا دعاءُ الأتباعِ على المتبوعين المُضِلّين بمضاعفةِ العذاب؛ فاحذر أن تكون سببًا في ضلالِ غيرك بدعوتك إلى باطلٍ أو تزيينِ معصيةٍ أو سنِّ سنّةٍ سيّئة، فيدعو عليك من أضللته، ويُضاعَف عذابك؛ فالمُضِلُّ يحمل وزرَ ضلالِه ووزرَ من أضلّهم؛ ومن دعا إلى ضلالةٍ كان عليه من الإثمِ مثلُ آثامِ من تبعه؛ فادعُ إلى الخيرِ والهدى، لا إلى الشرِّ والضلال؛ ولا تكن ممّن يزيّن للناسِ المعاصيَ ويدعوهم إليها؛ فإنّ تبعتها عظيمة؛ فاجعل أثرك في الناسِ خيرًا: تدعوهم إلى الحقِّ والطاعة، وتنهاهم عن الباطلِ والمعصية؛ فمن كان مفتاحًا للخيرِ مغلاقًا للشرِّ فطوبى له؛ ومن كان مفتاحًا للشرِّ مغلاقًا للخيرِ فويلٌ له؛ فكن داعيةً للخير، محذّرًا من الشر؛ فبذلك تسلم من دعاءِ المُضَلّين عليك."}},{"n":62,"reflection":{"text":"«وقالوا ما لنا لا نرى رجالا كنا نعدهم من الأشرار» — وقال أهلُ النارِ متعجّبين: ما بالنا لا نرى معنا في النارِ رجالًا كنا نعدّهم في الدنيا من الأشرارِ الأراذل (وهم المؤمنون الذين سخروا منهم)؛ ففي هذا ندمُ الكافرين على احتقارِ المؤمنين؛ فاحذر احتقارَ المؤمنين والاستهزاءَ بهم، فربّ محتقَرٍ عند الناسِ رفيعٌ عند الله، فلا تزدرِ أحدًا من المؤمنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من احتقارِ المؤمنين والاستهزاءِ بهم."},"action":{"text":"تأمّل ندمَ أهلِ النارِ وتفقّدهم للمؤمنين: قالوا متعجّبين ما بالنا لا نرى معنا في النارِ رجالًا كنا نعدّهم في الدنيا من الأشرارِ الأراذلِ ونحتقرهم — وهم المؤمنون الضعفاءُ الذين سخر منهم الكفّار «وقالوا ما لنا لا نرى رجالا كنا نعدهم من الأشرار»؛ ففي هذا ندمُ الكافرين على احتقارهم للمؤمنين واستهزائهم بهم في الدنيا؛ فقد كانوا يحتقرونهم، فإذا هم في أعلى الدرجاتِ في الجنّة؛ فاحذر احتقارَ المؤمنين والاستهزاءَ بهم لفقرهم أو ضعفهم أو قلّةِ حظّهم من الدنيا؛ فربّ محتقَرٍ عند الناسِ رفيعُ القدرِ عند الله؛ فربّ أشعثَ أغبرَ مدفوعٍ بالأبوابِ لو أقسم على الله لأبرّه؛ فلا تزدرِ أحدًا من المؤمنين ولو كان فقيرًا ضعيفًا؛ فليس الشرفُ بالمالِ والجاه، بل بالتقوى والإيمان؛ إنّ أكرمكم عند الله أتقاكم؛ فاحفظ المؤمنين، ووقّرهم، ولا تحتقر منهم أحدًا؛ فلا تدري لعلّ من تحتقره خيرٌ منك عند الله؛ فاحذر الاستهزاءَ بالمؤمنين؛ فإنّ عاقبتَه الندمُ يومَ القيامة؛ فأحبّ المؤمنين، ووقّرهم، ولا تسخر منهم؛ فمن سخر من مؤمنٍ لدينِه أو فقرِه فقد عرّض نفسه لمقتِ الله."}},{"n":63,"reflection":{"text":"«أتخذناهم سخريا أم زاغت عنهم الأبصار» — أكنا نتّخذهم موضعَ سخريةٍ ظلمًا، أم أنهم معنا في النارِ لكن أبصارنا لا تراهم؟ ففي هذا اعترافهم بخطأِ سخريتهم من المؤمنين؛ فاحذر السخريةَ من عبادِ الله الصالحين، فإنها ظلمٌ يُندَم عليه، فأكرم المؤمنين ولا تسخر منهم، فالسخريةُ من المؤمنين عاقبتها الحسرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ السخريةِ من الصالحين، وإكرامُهم لا احتقارُهم."},"action":{"text":"تأمّل حيرةَ أهلِ النارِ وندمهم: قالوا أكنا نتّخذ هؤلاء المؤمنين موضعَ سخريةٍ واستهزاءٍ في الدنيا ظلمًا وخطأً منّا؟ أم أنهم معنا في النارِ لكن أبصارنا زاغت عنهم فلا نراهم؟ «أتخذناهم سخريا أم زاغت عنهم الأبصار»؛ فتيقّنوا أنهم أخطؤوا في سخريتهم منهم، وأنّ المؤمنين في الجنّةِ لا في النار؛ ففي هذا اعترافهم بخطأِ سخريتهم من المؤمنين وندمهم عليها؛ فاحذر السخريةَ من عبادِ الله الصالحين والمؤمنين؛ فإنها ظلمٌ وخطأٌ يُندَم عليه أشدَّ الندم؛ يا أيها الذين آمنوا لا يسخر قومٌ من قومٍ عسى أن يكونوا خيرًا منهم؛ فأكرم المؤمنين والصالحين، ولا تسخر منهم ولا تحتقرهم؛ فالسخريةُ من المؤمنين عاقبتها الحسرةُ والندامةُ يومَ القيامة؛ فكم من مستهزئٍ بالصالحين في الدنيا تمنّى في الآخرةِ لو كان معهم؛ فوقّر أهلَ الدينِ والصلاح، وأحبّهم، واجلس إليهم؛ ولا تسخر من عابدٍ لعبادته، ولا من فقيرٍ لفقره، ولا من مبتلًى لبلائه؛ فالعاقبةُ للمتّقين، ولو احتقرهم أهلُ الدنيا؛ فاحفظ لسانك عن السخريةِ من المؤمنين؛ فإنها من كبائرِ الأخلاقِ وموبقاتها."}},{"n":64,"reflection":{"text":"«إن ذلك لحق تخاصم أهل النار» — إنّ ذلك التخاصمَ والتلاومَ بين أهلِ النارِ لحقٌّ واقعٌ لا محالة؛ ففي هذا تأكيدُ وقوعِ تخاصمِ أهلِ النار؛ فاعلم أنّ تخاصمَ أهلِ النارِ وتلاومهم حقٌّ، فاحذر أن تكون منهم، واعمل لتكون من أهلِ الجنّةِ المتحابّين، فأهلُ النارِ يتخاصمون وأهلُ الجنّةِ يتحابّون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوقوعِ تخاصمِ أهلِ النار، والعملُ للنجاةِ منه."},"action":{"text":"اعلم أنّ الله أكّد أنّ ذلك التخاصمَ والتلاومَ والتلاعنَ بين أهلِ النار — بين المتبوعين والتابعين، والمُضِلّين والمُضَلّين — حقٌّ واقعٌ لا محالة يومَ القيامة «إن ذلك لحق تخاصم أهل النار»؛ ففي هذا تأكيدُ وقوعِ تخاصمِ أهلِ النارِ وتلاومهم؛ فاعلم أنّ هذا التخاصمَ والتلاعنَ بين أهلِ النارِ حقٌّ سيقع؛ فاحذر أن تكون منهم، من أهلِ الكفرِ والطغيانِ والضلالِ والإضلال؛ واعمل لتكون من أهلِ الجنّةِ المتحابّين المتآخين؛ فأهلُ النارِ يتخاصمون ويتلاعنون ويتبرّأ بعضهم من بعض، وأهلُ الجنّةِ إخوانٌ متحابّون على سررٍ متقابلين؛ ونزعنا ما في صدورهم من غلٍّ إخوانًا؛ فاختر لنفسك: أتكون مع المتخاصمين المتلاعنين في النار، أم مع المتحابّين المتآخين في الجنّة؟ فاعمل عملَ أهلِ الجنّةِ من الإيمانِ والتقوى والمحبّةِ في الله؛ واجتنب عملَ أهلِ النارِ من الكفرِ والطغيانِ والعداوةِ والإضلال؛ فالمتحابّون في الله على منابرَ من نورٍ يومَ القيامة؛ فأحبّ في الله، واعمل للنجاةِ من النارِ وتخاصمِ أهلها؛ فالنجاةُ في الإيمانِ والتقوى والأخوّةِ في الله."}}]},{"title":"توحيدُ الله الواحدِ القهّار، والنبأُ العظيم، وخبرُ الملأ الأعلى","range":[65,70],"theme":"أمرُ النبيِّ أن يعلن أنه منذِرٌ وأنه لا إله إلا الله الواحدُ القهّارُ ربُّ السماواتِ والأرضِ العزيزُ الغفّار، وأنّ ما جاء به نبأٌ عظيمٌ هم عنه معرضون، وأنّ إخباره بخصومةِ الملأ الأعلى في شأنِ آدمَ إنما هو بالوحيِ الدالِّ على نبوّته، وأنّ وظيفتَه الإنذارُ المبين","verses":[{"n":65,"reflection":{"text":"«قل إنما أنا منذر وما من إله إلا الله الواحد القهار» — قل يا محمدُ: إنما أنا منذِرٌ أخوّفكم عاقبةَ الكفر، وما من معبودٍ بحقٍّ إلا الله الواحدُ في ذاته وصفاته، القهّارُ لكلِّ شيء؛ ففي هذا تقريرُ التوحيدِ ووظيفةِ الرسول؛ فوحّد الله الواحدَ القهّار، واحذر عاقبةَ مخالفةِ النذير، فالله وحده المعبودُ القاهرُ، فأخلص له العبادةَ والخوف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله الواحدِ القهّار، واتّعاظٌ بإنذارِ الرسول."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله: إنما أنا منذِرٌ أخوّفكم عاقبةَ الكفرِ والمعاصي، وما من معبودٍ بحقٍّ إلا الله الواحدُ الأحدُ في ذاته وأسمائه وصفاته، القهّارُ الذي قهر كلَّ شيءٍ وخضع له كلُّ شيء «قل إنما أنا منذر وما من إله إلا الله الواحد القهار»؛ ففي هذا تقريرُ التوحيدِ الخالص، وبيانُ وظيفةِ الرسولِ وهي الإنذارُ والبلاغ؛ فوحّد الله الواحدَ القهّار؛ فهو الواحدُ الذي لا شريكَ له، القهّارُ الذي قهر جميعَ خلقه بعزّته وقدرته؛ فأخلص له العبادةَ والخوفَ والرجاءَ والتوكّل؛ ولا تعبد معه سواه؛ فمن عرف أنّ الله واحدٌ قهّارٌ أفرده بالعبادةِ وخافه؛ فالقهّارُ الذي قهر العبادَ بالموتِ والفناء، ودانت له الرقاب، وخضعت لعظمته المخلوقات؛ فكيف يُعبَد معه غيرُه وهو القاهرُ لكلِّ شيء؟ فاتّعظ بإنذارِ الرسولِ ﷺ، واحذر عاقبةَ مخالفتِه؛ فما جاء إلا نذيرًا مبلّغًا؛ فمن أطاعه نجا، ومن عصاه هلك؛ فوحّد الله، وأطع رسوله، واتّعظ بإنذاره؛ فالله الواحدُ القهّارُ وحده المستحقُّ للعبادة."}},{"n":66,"reflection":{"text":"«رب السماوات والأرض وما بينهما العزيز الغفار» — هو ربُّ السماواتِ والأرضِ وما بينهما، العزيزُ الغالبُ، الغفّارُ لمن تاب؛ ففي هذا الجمعُ بين ربوبيتِه وعزّتِه ومغفرتِه؛ فاعبد ربَّ كلِّ شيءٍ العزيزَ الغفّار، وارجُ مغفرتَه وأنت تخاف عزّته، فمن عرف أنه العزيزُ الغفّارُ جمع بين الخوفِ والرجاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الربِّ العزيزِ الغفّار، والجمعُ بين الخوفِ والرجاء."},"action":{"text":"تأمّل وصفَ الله نفسه بعد تقريرِ توحيده: هو ربُّ السماواتِ والأرضِ وما بينهما، خالقها ومالكها ومدبّرها، العزيزُ الغالبُ الذي لا يُغالَب، الغفّارُ الذي يغفر الذنوبَ لمن تاب وأناب «رب السماوات والأرض وما بينهما العزيز الغفار»؛ ففي هذا الجمعُ بين ربوبيتِه الشاملةِ وعزّتِه القاهرةِ ومغفرتِه الواسعة؛ فاعبد ربَّ كلِّ شيءٍ، العزيزَ الغفّار؛ وارجُ مغفرتَه وأنت تخاف عزّته وعقابه؛ فمن عرف أنّ الله عزيزٌ غفّار جمع بين الخوفِ من عزّته والرجاءِ لمغفرته؛ فاجمع في قلبك بين الخوفِ والرجاء؛ فلا تأمن مكرَ الله لعزّته، ولا تيأس من رحمتِه لمغفرته؛ فهو شديدُ العقابِ ذو الطول، غافرُ الذنبِ وقابلُ التوب؛ فاعبده راجيًا خائفًا؛ فالخوفُ يمنعك من المعاصي، والرجاءُ يحملك على الطاعةِ والتوبة؛ فمن عبد الله بالخوفِ وحده يئس، ومن عبده بالرجاءِ وحده أمِن، ومن عبده بهما جميعًا اهتدى؛ فاجعل قلبك بين الخوفِ من عزّةِ الله والرجاءِ لمغفرته؛ فبهما يستقيم سيرُك إلى الله؛ فارجُ مغفرةَ الغفّار، واخشَ عقابَ العزيز؛ فبالخوفِ والرجاءِ تسلك الصراطَ المستقيم."}},{"n":67,"reflection":{"text":"«قل هو نبأ عظيم» — قل يا محمدُ: هذا القرآنُ (أو أمرُ البعثِ والتوحيد) خبرٌ عظيمُ الشأن؛ ففي هذا تعظيمُ شأنِ القرآنِ والوحي؛ فعظّم شأنَ القرآنِ في قلبك، وأعطه قدره، فالقرآنُ نبأٌ عظيمٌ لا يليق أن يُعرَض عنه، فاعتنِ به وأقبل عليه بما يليق بعظمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ شأنِ القرآنِ والإقبالُ عليه بما يليق بعظمته."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله عن القرآنِ وما فيه من التوحيدِ والبعثِ والوعدِ والوعيد: قل هو نبأٌ عظيمُ الشأنِ خطيرُ الأمر «قل هو نبأ عظيم»؛ ففي هذا تعظيمُ شأنِ القرآنِ والوحيِ وما جاء به من الحق؛ فعظّم شأنَ القرآنِ في قلبك، وأعطه قدره ومنزلته؛ فالقرآنُ نبأٌ عظيمٌ، وخبرٌ جليلٌ، لا يليق بعاقلٍ أن يُعرَض عنه أو يستهين به؛ فاعتنِ بالقرآنِ وأقبل عليه بما يليق بعظمته: تلاوةً وتدبّرًا وتعظيمًا وعملًا وتحكيمًا؛ فمن عظّم القرآنَ عظّمه الله؛ فلا تهجر القرآن، ولا تستخفّ به، ولا تعرض عنه؛ بل أعطه حقّه من التعظيمِ والاعتناء؛ فهو كلامُ الله العظيم، وحبله المتين، ونوره المبين؛ فتعظيمُ القرآنِ من تعظيمِ الله؛ فاجعل للقرآنِ في قلبك المكانةَ اللائقةَ به؛ واستشعر عظمةَ ما تقرأ من كلامِ ربك؛ فمن استشعر عظمةَ القرآنِ خشع قلبه وانتفع به؛ فأقبل على هذا النبأِ العظيمِ بقلبٍ معظّمٍ خاشعٍ متدبّر."}},{"n":68,"reflection":{"text":"«أنتم عنه معرضون» — أنتم أيها المكذّبون عن هذا النبأِ العظيمِ معرضون غافلون؛ ففي هذا توبيخُ المعرضين عن القرآن؛ فاحذر الإعراضَ عن القرآنِ والغفلةَ عنه، فإنه أعظمُ الخسران، فأقبل على القرآنِ ولا تعرض عنه، فالإعراضُ عن أعظمِ نبأٍ حماقةٌ وخسارة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإعراضِ عن القرآن، والإقبالُ عليه."},"action":{"text":"اعلم أنّ الله وبّخ المكذّبين على إعراضهم عن القرآنِ العظيم مع عظمِ شأنه: أنتم أيها المكذّبون عن هذا النبأِ العظيمِ معرضون غافلون لاهون «أنتم عنه معرضون»؛ ففي هذا توبيخُ المعرضين عن القرآنِ وذمّهم؛ فأيُّ حماقةٍ أعظمُ من الإعراضِ عن أعظمِ نبأٍ وأجلِّ خبر؟ فاحذر الإعراضَ عن القرآنِ والغفلةَ عنه وهجرَه؛ فإنّ الإعراضَ عنه من أعظمِ الخسران؛ ومن أعرض عن ذكري فإنّ له معيشةً ضنكًا؛ فأقبل على القرآنِ بالتلاوةِ والتدبّرِ والعملِ والتحكيم، ولا تعرض عنه؛ فالإعراضُ عن أعظمِ نبأٍ ووحيٍ حماقةٌ وخسارةٌ وضلال؛ فكم من غافلٍ معرضٍ عن القرآن، مقبلٍ على سفاسفِ الأمورِ وتفاهاتها؛ فلا تكن منهم؛ بل اجعل القرآنَ ربيعَ قلبك ونورَ صدرك؛ فمن أقبل على القرآنِ أقبلت عليه السعادةُ والهداية، ومن أعرض عنه أعرضت عنه؛ فبادر بالإقبالِ على القرآن؛ فلا يليق بعاقلٍ يعرف عظمةَ القرآنِ أن يعرض عنه؛ فأقبل عليه، واعتنِ به، ولا تكن من المعرضين."}},{"n":69,"reflection":{"text":"«ما كان لي من علم بالملإ الأعلى إذ يختصمون» — ما كان لي علمٌ بأمرِ الملائكةِ في الملأ الأعلى حين اختصموا (في شأنِ آدم) لولا الوحي؛ ففي هذا إثباتُ نبوّتِه بإخباره بالغيبِ عن طريقِ الوحي؛ فاعلم أنّ ما جاء به النبيُّ من أخبارِ الغيبِ دليلُ صدقه، فآمن بما أخبر به عن الغيب، فالوحيُ وحده مصدرُ علمِ الغيبِ الصادق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بأخبارِ الغيبِ من الوحي، وأنها دليلُ صدقِ النبوّة."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله مبيّنًا أنّ علمه بالغيبِ إنما هو بالوحي: ما كان لي من علمٍ بأمرِ الملائكةِ في الملأ الأعلى حين اختصموا في شأنِ خلقِ آدمَ والسجودِ له، لولا أن أوحى الله إليّ ذلك «ما كان لي من علم بالملإ الأعلى إذ يختصمون»؛ ففي هذا إثباتُ نبوّتِه بإخباره بالغيبِ الذي لا يُعلَم إلا بالوحي؛ فإخبارُه بما جرى في الملأ الأعلى من غيرِ تعلّمٍ ولا قراءةٍ دليلٌ على صدقِ نبوّته؛ فاعلم أنّ ما جاء به النبيُّ ﷺ من أخبارِ الغيبِ الماضيةِ والآتية دليلٌ قاطعٌ على صدقه ونبوّته؛ فما كان يعلمها إلا بوحيٍ من الله؛ فآمن بما أخبر به النبيُّ عن الغيب، وصدّقه؛ فالوحيُ وحده مصدرُ علمِ الغيبِ الصادق؛ فلا يُعلَم الغيبُ إلا من طريقِ الوحي؛ فمن ادّعى علمَ الغيبِ من غيرِ طريقِ الوحيِ فهو كاذب؛ قل لا يعلم من في السماواتِ والأرضِ الغيبَ إلا الله؛ فآمن بأخبارِ الغيبِ التي أخبر بها الوحيُ الصادق؛ فهي من دلائلِ صدقِ الرسالة؛ فصدّق النبيَّ فيما أخبر، واعتصم بالوحيِ في معرفةِ الغيب."}},{"n":70,"reflection":{"text":"«إن يوحى إلي إلا أنما أنا نذير مبين» — ما يُوحى إليّ إلا لأني نذيرٌ مبيّنٌ أخوّفكم وأبيّن لكم؛ ففي هذا بيانُ أنّ وظيفةَ الرسولِ الإنذارُ والبيان؛ فتقبّل إنذارَ النبيِّ وبيانه، واتّعظ بما جاء به، فالنبيُّ نذيرٌ مبيّن، فمن اتّعظ بإنذاره نجا، فلا تعرض عن نذيرِ الله وبيانه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقبّلُ إنذارِ النبيِّ وبيانِه، والاتّعاظُ بما جاء به."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله: ما يُوحى إليّ هذا الوحيُ إلا لأني نذيرٌ مبيّنٌ، أخوّفكم عاقبةَ الكفرِ والمعاصي، وأبيّن لكم الحقَّ من الباطلِ بيانًا واضحًا «إن يوحى إلي إلا أنما أنا نذير مبين»؛ ففي هذا بيانُ أنّ من أعظمِ وظائفِ الرسولِ الإنذارَ والبيان؛ فتقبّل إنذارَ النبيِّ ﷺ وبيانه، واتّعظ بما جاء به من الوحي؛ فالنبيُّ نذيرٌ مبيّنٌ، جاء ليخوّفك من عذابِ الله ويبيّن لك طريقَ النجاة؛ فمن اتّعظ بإنذاره واتّبع بيانه نجا، ومن أعرض عنه هلك؛ فلا تعرض عن نذيرِ الله وبيانه؛ بل اقبل النذارةَ بالإيمانِ والعمل، واتّبع البيانَ بالطاعةِ والاهتداء؛ فقد أرسل الله رسوله بالهدى ودينِ الحقِّ نذيرًا وبشيرًا؛ فاجعل نفسك ممّن ينتفع بإنذارِ النبيِّ وبيانه؛ فالإنذارُ رحمةٌ بك لتنجو؛ فقابله بالإقبالِ والاتّباعِ والاتّعاظ؛ فمن نفعه إنذارُ النبيِّ اتّقى، ومن ضرّه إعراضُه هلك؛ فاتّبع النذيرَ المبيّن، وانتفع بهديه؛ فبه النجاةُ والفوز."}}]},{"title":"قصةُ خلقِ آدمَ وسجودِ الملائكة، وكِبرُ إبليسَ وطردُه واستنظارُه وإغواؤه","range":[71,85],"theme":"إخبارُ الله الملائكةَ بخلقِ آدمَ من طينٍ والأمرُ بالسجودِ له بعد نفخِ الروح، وسجودُهم أجمعين إلا إبليسَ استكبر، ومحاجّةُ الله له وقياسُه الفاسدُ بأنه خيرٌ من آدم، وطردُه ولعنتُه إلى يومِ الدين، واستنظارُه إلى الوقتِ المعلوم، وإقسامُه على إغواءِ بني آدمَ أجمعين إلا المخلصين، وتأكيدُ الله وعيدَه بملءِ جهنمَ منه وممّن تبعه","verses":[{"n":71,"reflection":{"text":"«إذ قال ربك للملائكة إني خالق بشرا من طين» — حين قال ربّك للملائكة: إني خالقٌ بشرًا من طين (وهو آدم)؛ ففي هذا بيانُ أصلِ خلقِ الإنسانِ من طين؛ فتذكّر أصلك من الطين، فلا تتكبّر، فمن كان أصله من طينٍ لا يليق به الكِبر، فتواضع لله وللخلق، فالتواضعُ يليق بمن أصله من طين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ الأصلِ من الطين، والتواضعُ ونبذُ الكِبر."},"action":{"text":"تأمّل بدءَ قصّةِ خلقِ آدم: حين قال ربّك للملائكةِ مخبرًا لهم بما سيكون: إني خالقٌ بشرًا من طين، وهو آدمُ أبو البشر «إذ قال ربك للملائكة إني خالق بشرا من طين»؛ ففي هذا بيانُ أصلِ خلقِ الإنسانِ من الطين، وتكريمِ الله له بأن تولّى خلقه وأخبر ملائكته به؛ فتذكّر أصلك أيها الإنسانُ من الطين؛ فلا تتكبّر ولا تتجبّر؛ فمن كان أصله من طينٍ ومنتهاه إلى جيفةٍ منتنة، وهو بينهما يحمل العذرة، لا يليق به الكِبرُ والفخر؛ فتواضع لله وللخلق؛ فالتواضعُ يليق بمن أصله من طينٍ حقير؛ فما للإنسانِ والكِبر، وأصله نطفةٌ ثم علقة، وخُلِق من طين؟ فاعرف قدرك، وتذكّر أصلك، وتواضع؛ فمن تواضع لله رفعه؛ فالكِبرُ رداءُ الله، فمن نازعه إيّاه عذّبه؛ فاطرح الكِبرَ والعُجب؛ وتذكّر أنّ عزّك وشرفك ليس بأصلِ طينتك، بل بتقواك وطاعتِك لله؛ فتواضع، واذكر أصلك ومنتهاك، تسلم من آفةِ الكِبرِ التي أهلكت إبليس."}},{"n":72,"reflection":{"text":"«فإذا سويته ونفخت فيه من روحي فقعوا له ساجدين» — فإذا أتممتُ خلقَه ونفختُ فيه الروحَ فاسجدوا له تكريمًا وطاعةً لي؛ ففي هذا تكريمُ الله لآدمَ وأمرُ الملائكةِ بالسجودِ له؛ فاعلم أنّ الطاعةَ لله في أمره واجبة، فأطع أمرَ الله ولو لم تدرك حكمته، فالملائكةُ أُمِروا بالسجودِ فأطاعوا، فالطاعةُ لأمرِ الله سبيلُ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطاعةُ لأمرِ الله ولو لم تُدرَك الحكمة."},"action":{"text":"تأمّل أمرَ الله للملائكة: فإذا أتممتُ خلقَ آدمَ وسوّيته ونفختُ فيه من روحي — إضافةَ تشريفٍ وتكريم — فاسجدوا له سجودَ تحيّةٍ وتكريمٍ وطاعةً لأمري «فإذا سويته ونفخت فيه من روحي فقعوا له ساجدين»؛ ففي هذا تكريمُ الله لآدمَ حيث أمر الملائكةَ بالسجودِ له؛ فاعلم أنّ طاعةَ الله في أمره واجبةٌ لازمة، سواء أدركت حكمته أم لم تدركها؛ فأطع أمرَ الله ولو لم تفهم حكمته؛ فالملائكةُ أُمِروا بالسجودِ لآدمَ فأطاعوا وامتثلوا بلا تردّد؛ فالعبوديةُ الكاملةُ أن تمتثل أمرَ الله لأنه أمرُ الله، لا لأنك أدركت حكمته؛ فما كان قولَ المؤمنين إذا دُعوا إلى الله ورسوله ليحكم بينهم إلا أن يقولوا سمعنا وأطعنا؛ فاجعل شعارك: سمعنا وأطعنا؛ فطاعةُ الله لأمره سبيلُ النجاةِ والفلاح؛ فمن أطاع أمرَ الله فقد نجا كالملائكة، ومن استكبر عنه فقد هلك كإبليس؛ فسلّم لأمرِ الله، وامتثله بلا اعتراضٍ ولا تردّد؛ فالحكمةُ في الطاعةِ ولو خفيت عليك؛ فأطع الله، وثق بحكمته، وسلّم لأمره."}},{"n":73,"reflection":{"text":"«فسجد الملائكة كلهم أجمعون» — فسجد الملائكةُ كلُّهم جميعًا امتثالًا لأمرِ الله بلا استثناء؛ ففي هذا كمالُ طاعةِ الملائكةِ وانقيادهم؛ فاقتدِ بالملائكةِ في المبادرةِ إلى الطاعةِ والامتثالِ التامّ، فالطاعةُ الكاملةُ أن تمتثل أمرَ الله فورًا بلا تردّد، فبادر إلى طاعةِ الله كما بادرت الملائكة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى الطاعةِ والامتثالُ التامّ، اقتداءً بالملائكة."},"action":{"text":"تأمّل كمالَ طاعةِ الملائكة: فسجد الملائكةُ كلُّهم جميعًا، بلا استثناءِ أحدٍ منهم، امتثالًا لأمرِ الله ومبادرةً إلى طاعته «فسجد الملائكة كلهم أجمعون»؛ ففي هذا كمالُ طاعةِ الملائكةِ وانقيادهم التامِّ لأمرِ الله؛ فسجدوا كلُّهم مبادرين ممتثلين بلا تأخّرٍ ولا تردّد؛ فاقتدِ بالملائكةِ في المبادرةِ إلى الطاعةِ والامتثالِ التامِّ لأمرِ الله؛ فالطاعةُ الكاملةُ أن تمتثل أمرَ الله فورًا بلا تردّدٍ ولا تسويفٍ ولا اعتراض؛ فبادر إلى طاعةِ الله كما بادرت الملائكة؛ فالملائكةُ لا يعصون الله ما أمرهم ويفعلون ما يُؤمَرون؛ فتشبّه بهم في سرعةِ الاستجابةِ وكمالِ الانقياد؛ فإذا أمرك الله بأمرٍ فبادر إليه، وإذا نهاك عن شيءٍ فانتهِ عنه؛ ولا تكن ممّن يسوّف ويتردّد ويعتذر؛ فسارعوا إلى مغفرةٍ من ربكم؛ فالمبادرةُ إلى الطاعةِ من علاماتِ صدقِ الإيمان؛ فكن سبّاقًا إلى الخيرِ كالملائكة؛ فمن بادر إلى طاعةِ الله فاز، ومن سوّف وتردّد خُذِل؛ فاجعل شأنك المسارعةَ والمبادرةَ إلى طاعةِ الله."}},{"n":74,"reflection":{"text":"«إلا إبليس استكبر وكان من الكافرين» — إلا إبليسَ استكبر عن السجودِ وأبى، وكان في علمِ الله من الكافرين؛ ففي هذا أنّ الكِبرَ عن أمرِ الله كفرٌ وهلاك؛ فاحذر الكِبرَ عن طاعةِ الله، فإنه أهلك إبليسَ وأخرجه من رحمةِ الله، فالكِبرُ عن الطاعةِ أصلُ كلِّ شرّ، فتواضع وأطع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ عن طاعةِ الله، فهو أهلك إبليس."},"action":{"text":"تأمّل كيف هلك إبليسُ بالكِبر: سجد الملائكةُ كلُّهم إلا إبليسَ، استكبر عن السجودِ وأبى امتثالَ أمرِ الله، وكان بذلك في علمِ الله من الكافرين «إلا إبليس استكبر وكان من الكافرين»؛ ففي هذا أنّ الكِبرَ عن أمرِ الله وطاعتِه كفرٌ وهلاكٌ وطرد؛ فإبليسُ ما كفر لجهلٍ بالله، بل كفر كِبرًا وعنادًا؛ فاحذر الكِبرَ عن طاعةِ الله وقبولِ الحق؛ فإنّ الكِبرَ أهلك إبليسَ وأخرجه من رحمةِ الله بعد أن كان في مصافِّ الملائكة؛ فالكِبرُ أوّلُ ذنبٍ عُصِي الله به؛ وهو أصلُ كلِّ شرٍّ وبلاء؛ فلا يدخل الجنّةَ من كان في قلبه مثقالُ ذرّةٍ من كبر؛ فطهّر قلبك من الكِبرِ والعُجبِ والاستكبار؛ وتواضع لله بالطاعةِ والانقياد، وللحقِّ بالقبول، وللخلقِ بحسنِ المعاملة؛ فمن تواضع لله رفعه، ومن استكبر وضعه؛ فاحذر أن تكون من أتباعِ إبليسَ في كِبره وعناده؛ بل كن من أتباعِ الملائكةِ في تواضعهم وطاعتهم؛ فالكِبرُ عن الطاعةِ سبيلُ الطردِ والهلاك، والتواضعُ لله سبيلُ الرفعةِ والنجاة؛ فتواضع وأطع، تنجُ وترتفع."}},{"n":75,"reflection":{"text":"«قال يا إبليس ما منعك أن تسجد لما خلقت بيدي أستكبرت أم كنت من العالين» — قال الله موبّخًا: يا إبليسُ ما منعك أن تسجد لآدمَ الذي خلقته بيديّ تشريفًا له؟ أاستكبرت الآن، أم كنت من المتكبّرين أصلًا؟ ففي هذا توبيخُ المستكبرِ ومحاسبتُه؛ فاعلم أنّ الله يحاسب على الكِبرِ عن طاعته، فحاسب نفسك: هل يمنعك الكِبرُ عن طاعةٍ أو قبولِ حق؟ فطهّر نفسك من موانعِ الطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ على موانعِ الطاعة، وتطهيرُها من الكِبر."},"action":{"text":"تأمّل توبيخَ الله لإبليس: قال يا إبليسُ ما الذي منعك أن تسجد لآدمَ الذي تولّيتُ خلقه بيديّ تكريمًا وتشريفًا له؟ أاستكبرت في هذا الموقف، أم كنت من المتكبّرين المتعالين أصلًا في طبعك؟ «قال يا إبليس ما منعك أن تسجد لما خلقت بيدي أستكبرت أم كنت من العالين»؛ ففي هذا محاسبةُ الله للمستكبرِ وتوبيخُه على ترْكِ الطاعة؛ فاعلم أنّ الله يحاسب العبدَ على ما منعه من طاعته؛ فحاسب نفسك: ما الذي يمنعك من طاعةِ الله أو قبولِ الحقِّ أو أداءِ الواجب؟ أهو الكِبرُ والأنفةُ، أم الهوى والشهوة، أم حبُّ الدنيا؟ فطهّر نفسك من موانعِ الطاعة؛ فإذا وجدت في نفسك مانعًا يصدّك عن طاعةٍ أو يحملك على معصيةٍ فجاهده واقلعه؛ فالكِبرُ والعُجبُ والهوى والحسدُ كلُّها موانعُ من الطاعةِ والهداية؛ فراقب قلبك، واكشف ما يمنعك من الخير؛ فمن عرف داءه أمكنه دواؤه؛ فحاسب نفسك قبل أن تُحاسَب؛ وطهّر قلبك من الكِبرِ الذي أهلك إبليس؛ فما منع أحدًا من الحقِّ والطاعةِ إلا كِبرٌ أو هوًى؛ فاقلع موانعَ الطاعة، وبادر إلى الامتثال."}},{"n":76,"reflection":{"text":"«قال أنا خير منه خلقتني من نار وخلقته من طين» — قال إبليسُ محتجًّا بجهله: أنا خيرٌ من آدم، خلقتني من نار وخلقته من طين؛ ففي هذا أصلُ قياسِ إبليسَ الفاسدِ في معارضةِ النصِّ بالرأي؛ فاحذر معارضةَ أمرِ الله برأيك وقياسك، فإبليسُ عارض الأمرَ بقياسه فهلك، فسلّم لأمرِ الله ولا تعارضه بعقلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من معارضةِ أمرِ الله بالرأيِ والقياسِ الفاسد."},"action":{"text":"تأمّل حجّةَ إبليسَ الفاسدة: قال محتجًّا بقياسٍ باطلٍ من كِبره: أنا خيرٌ من آدم، فقد خلقتني من نارٍ وخلقته من طين، والنارُ خيرٌ من الطين «قال أنا خير منه خلقتني من نار وخلقته من طين»؛ فعارض أمرَ الله بالسجودِ بقياسه الفاسدِ ورأيه المنحرف؛ ففي هذا أصلُ ضلالِ إبليسَ: معارضةُ النصِّ الصريحِ بالرأيِ والقياس؛ فاحذر معارضةَ أمرِ الله ونصوصِ الوحيِ برأيك وقياسك وعقلك؛ فإبليسُ عارض أمرَ الله بقياسه فكفر وهلك؛ فأوّلُ من قاس قياسًا فاسدًا في مقابلةِ النصِّ إبليس؛ فمن قدّم رأيه وقياسه على أمرِ الله ونصِّ الوحيِ فقد ضلّ؛ فسلّم لأمرِ الله ونصوصِ شرعه، ولا تعارضها بعقلك وهواك وقياسك؛ فإذا جاء النصُّ بطل الرأيُ والقياسُ المخالف؛ فلا رأيَ لأحدٍ مع أمرِ الله ورسوله؛ وما كان لمؤمنٍ ولا مؤمنةٍ إذا قضى الله ورسوله أمرًا أن يكون لهم الخيرةُ من أمرهم؛ فسلّم وانقد؛ ولا تحكّم عقلك وقياسك في مقابلةِ الوحي؛ فمن سلّم للنصِّ نجا، ومن عارضه بقياسه هلك كإبليس؛ فقدّم أمرَ الله على كلِّ رأيٍ وقياسٍ وهوى."}},{"n":77,"reflection":{"text":"«قال فاخرج منها فإنك رجيم» — قال الله: فاخرج من الجنّةِ أو من السماء، فإنك مطرودٌ ملعون؛ ففي هذا جزاءُ الكِبرِ والعصيان: الطردُ والإبعاد؛ فاعلم أنّ معصيةَ الله والكِبرَ عن أمره سببُ الطردِ من رحمتِه، فاحذر ما يبعدك عن الله، والزم طاعتَه لتبقى في قربه، فالعصيانُ يطرد من رحمةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من المعصيةِ المبعِدةِ عن الله، ولزومُ الطاعة."},"action":{"text":"تأمّل جزاءَ إبليسَ على كِبره وعصيانه: قال الله له: فاخرج من الجنّةِ ومن منازلِ الكرامة، فإنك مطرودٌ مرجومٌ ملعونٌ مبعَدٌ من رحمتي «قال فاخرج منها فإنك رجيم»؛ ففي هذا أنّ جزاءَ الكِبرِ والعصيانِ الطردُ والإبعادُ من رحمةِ الله ومنازلِ الكرامة؛ فاعلم أنّ معصيةَ الله والاستكبارَ عن أمره سببُ الطردِ من رحمتِه والإبعادِ عن قربه؛ فإبليسُ كان في مصافِّ الملائكةِ فطُرِد بمعصيةٍ واحدةٍ من كبر؛ فاحذر ما يبعدك عن الله من المعاصي والكِبرِ والإصرار؛ والزم طاعةَ الله لتبقى في قربه ورحمته؛ فالطاعةُ تقرّب من الله، والمعصيةُ تبعّد عنه؛ فكم من طاعةٍ أدنت عبدًا من ربه، وكم من معصيةٍ أبعدت عبدًا وطردته؛ فراقب أعمالك: أتقرّبك من الله أم تبعدك عنه؟ فلازم ما يقرّبك، واجتنب ما يبعدك؛ فاحرص على أسبابِ القربِ من الطاعةِ والتوبةِ والذكر؛ واجتنب أسبابَ البعدِ من الكِبرِ والمعصيةِ والإصرار؛ فمن أطاع الله قرّبه، ومن عصاه وتكبّر طرده كما طرد إبليس؛ فالزم الطاعةَ لتبقى في قربِ الله ورحمته."}},{"n":78,"reflection":{"text":"«وإن عليك لعنتي إلى يوم الدين» — وإنّ عليك طردي وإبعادي ولعنتي إلى يومِ الجزاء؛ ففي هذا دوامُ لعنةِ الله على إبليس؛ فاحذر أسبابَ اللعنةِ والطردِ من رحمةِ الله، فمن استكبر وعصى استحقّ اللعنة، فالزم طاعةَ الله وتوبته لتنال رحمته لا لعنته، فاطلب رحمةَ الله بالطاعةِ والتوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أسبابِ اللعنة، وطلبُ رحمةِ الله بالطاعةِ والتوبة."},"action":{"text":"تأمّل عقوبةَ إبليس: وإنّ عليك طردي ولعنتي وإبعادي من رحمتي إلى يومِ الدينِ والجزاء «وإن عليك لعنتي إلى يوم الدين»؛ ففي هذا دوامُ لعنةِ الله وطردِه لإبليسَ بسببِ كِبره وعصيانه؛ فاحذر أسبابَ اللعنةِ والطردِ من رحمةِ الله، من الكِبرِ والعصيانِ والإصرار؛ فمن استكبر عن طاعةِ الله وعصاه معاندًا استحقّ اللعنةَ والطرد؛ فلا تعرّض نفسك لأسبابِ لعنةِ الله؛ فقد لعن الله أقوامًا بمعاصٍ معيّنةٍ في كتابه؛ فاجتنب المعاصيَ التي يُلعَن فاعلها؛ والزم طاعةَ الله والتوبةَ إليه لتنال رحمته لا لعنته؛ فرحمةُ الله قريبةٌ من المحسنين، ولعنتُه على الظالمين المستكبرين؛ فاطلب رحمةَ الله بالطاعةِ والإحسانِ والتوبةِ والإنابة؛ ولا تطلب سخطه ولعنته بالكِبرِ والعصيانِ والإصرار؛ فمن أطاع الله وأناب إليه رحمه، ومن استكبر وعصى وأصرّ لعنه وطرده؛ فاجعل عملك سببًا لرحمةِ الله، لا سببًا للعنته؛ فبادر بالتوبةِ والطاعة، واطلب رحمةَ الرحمن؛ فرحمتُه سبقت غضبه، وهي واسعةٌ لمن تاب وأناب."}},{"n":79,"reflection":{"text":"«قال رب فأنظرني إلى يوم يبعثون» — قال إبليسُ: ربِّ أمهلني وأخّر عذابي إلى يومِ يُبعَث الناس؛ ففي هذا طلبُ إبليسَ الإمهالَ ليُغويَ لا ليتوب؛ ففرقٌ بين من يطلب المهلةَ للتوبةِ ومن يطلبها للمعصية؛ فاغتنم مهلةَ عمرك للتوبةِ والطاعة، لا للإصرارِ على المعصية، فالمهلةُ نعمةٌ إن استُعمِلت في الطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ مهلةِ العمرِ للتوبةِ والطاعةِ لا للمعصية."},"action":{"text":"تأمّل طلبَ إبليسَ الإمهال: قال ربِّ أمهلني وأخّرني ولا تعذّبني إلى يومِ يُبعَث الناسُ من قبورهم «قال رب فأنظرني إلى يوم يبعثون»؛ فطلب المهلةَ لا ليتوب ويصلح، بل ليُغويَ بني آدمَ ويضلّهم؛ ففي هذا فرقٌ عظيمٌ بين من يطلب المهلةَ والعمرَ للتوبةِ والطاعةِ والإصلاح، ومن يطلبها للإصرارِ على المعصيةِ والإفساد؛ فاغتنم أنت مهلةَ عمرك وأيّامك للتوبةِ والطاعةِ والعملِ الصالح، لا للإصرارِ على المعصيةِ والغفلة؛ فالعمرُ مهلةٌ ونعمةٌ إن استُعمِل في طاعةِ الله؛ ونقمةٌ إن استُعمِل في معصيته؛ فكم من ممهَلٍ أطال الله عمره فزاد خيرًا وطاعة، وكم من ممهَلٍ زاد شرًّا وطغيانًا؛ فلا يكن طولُ العمرِ عليك لا لك؛ فالمعمَّرُ من أُنذِر؛ فمن عُمِّر ستّين سنةً فقد أعذر الله إليه في العمر؛ فاجعل بقيّةَ عمرك في التوبةِ والطاعةِ والاستعدادِ للقاءِ الله؛ ولا تكن كإبليسَ يطلب المهلةَ للإفسادِ والإضلال؛ بل اغتنم المهلةَ للإصلاحِ والطاعةِ والتزوّدِ للآخرة؛ فالسعيدُ من اغتنم مهلةَ عمره فيما ينفعه عند الله."}},{"n":80,"reflection":{"text":"«قال فإنك من المنظرين» — قال الله: فإنك من الممهَلين المؤخَّرين؛ ففي هذا إجابةُ الله لطلبِ إبليسَ الإمهالَ حكمةً وابتلاءً؛ فاعلم أنّ الله يمهل بحكمته ولا يهمل، فلا يغرّنك إمهالُ الله للعاصين، فالمهلةُ ابتلاءٌ لا إكرام، فاغتنم مهلتك أنت في طاعةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الإمهالَ ابتلاءٌ لا إكرام، واغتنامُه في الطاعة."},"action":{"text":"تأمّل إجابةَ الله لطلبِ إبليس: قال فإنك من الممهَلين المؤخَّرين الذين أُخّر عذابهم إلى أجلٍ معلوم «قال فإنك من المنظرين»؛ فأجاب الله طلبه لحكمةٍ بالغةٍ وابتلاءٍ لبني آدم، ليتبيّن من يتبع الحقَّ ممّن يتبع الشيطان؛ ففي هذا أنّ الله يمهل بحكمته ولا يهمل؛ فاعلم أنّ إمهالَ الله للعاصين والكافرين ابتلاءٌ وحكمة، لا إكرامٌ ولا رضا؛ فلا يغرّنك إمهالُ الله للظالمين والعاصين؛ ولا تظنّ أنّ تأخيرَ العقوبةِ رضًا أو نسيان؛ فإنّ الله يملي للظالمِ حتى إذا أخذه لم يفلته؛ وإنّ ربك لبالمرصاد؛ فالمهلةُ ابتلاءٌ واستدراج، لا إكرامٌ ولا أمان؛ فاغتنم أنت مهلتك وعمرك في طاعةِ الله والتوبةِ إليه؛ ولا تغترّ بالإمهال؛ فكم من ممهَلٍ أخذه الله بغتة؛ فبادر بالطاعةِ والتوبةِ ما دمت في زمنِ المهلة؛ فإنّ المهلةَ تنقضي، والأجلَ يأتي بغتة؛ فمن اغتنم مهلته في الطاعةِ فاز، ومن اغترّ بها وأصرّ على المعصيةِ خسر؛ فاجعل مهلةَ عمرك في مرضاةِ الله."}},{"n":81,"reflection":{"text":"«إلى يوم الوقت المعلوم» — إلى يومِ الوقتِ المعلومِ عند الله (وهو وقتُ النفخةِ الأولى أو أجلٌ حدّده الله)؛ ففي هذا أنّ آجالَ كلِّ شيءٍ محدّدةٌ عند الله؛ فاعلم أنّ لكلِّ أمرٍ أجلًا معلومًا عند الله، فسلّم لتقديرِ الله في الآجال، واعمل في وقتك المتاحِ قبل أن يأتيَ أجلك المعلوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لتقديرِ الله في الآجال، والعملُ قبل انقضائها."},"action":{"text":"تأمّل تحديدَ الله لأجلِ إمهالِ إبليس: إلى يومِ الوقتِ المعلومِ المحدّدِ عند الله، وهو وقتُ النفخةِ الأولى أو الأجلُ الذي حدّده الله بعلمه وحكمته «إلى يوم الوقت المعلوم»؛ ففي هذا أنّ آجالَ كلِّ شيءٍ محدّدةٌ معلومةٌ عند الله بمقاديره؛ فلا شيءَ يقع إلا في وقتِه المقدّرِ عند الله؛ فاعلم أنّ لكلِّ أمرٍ ولكلِّ نفسٍ أجلًا معلومًا عند الله لا يتقدّم ولا يتأخّر؛ فإذا جاء أجلهم لا يستأخرون ساعةً ولا يستقدمون؛ فسلّم لتقديرِ الله في الآجالِ والأوقات؛ ولا تعترض على حكمته في تأخيرِ أمرٍ أو تعجيله؛ فكلُّ شيءٍ عنده بمقدار؛ واعمل في وقتك المتاحِ قبل أن يأتيَ أجلك المعلوم؛ فأنت لا تدري متى ينقضي أجلك؛ فبادر بالعملِ الصالحِ ما دمت حيًّا؛ فإذا جاء الأجلُ انقطع العمل؛ فاغتنم حياتك قبل موتك، وصحّتك قبل سقمك، وفراغك قبل شغلك؛ فمن عمل في وقته قبل انقضاءِ أجله فاز، ومن سوّف حتى فاجأه الأجلُ ندم؛ فاعمل الآن، ولا تنتظر أجلك؛ فالآجالُ بيدِ الله، والعملُ في وقتك المتاح."}},{"n":82,"reflection":{"text":"«قال فبعزتك لأغوينهم أجمعين» — قال إبليسُ: فبعزّتك لأضلّنّ بني آدمَ أجمعين؛ ففي هذا عداوةُ إبليسَ لبني آدمَ وحرصُه على إغوائهم؛ فاحذر عدوّك إبليسَ الذي أقسم على إغوائك، فاتّخذه عدوًّا كما هو لك عدوّ، واستعذ بالله من كيده، فالغفلةُ عن عداوةِ الشيطانِ سببُ الوقوعِ في حبائله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عداوةِ الشيطان، واتّخاذُه عدوًّا والاستعاذةُ منه."},"action":{"text":"تأمّل إعلانَ إبليسَ عداوته لبني آدم: قال فبعزّتك يا ربِّ لأضلّنّ بني آدمَ أجمعين عن الحقِّ والهدى «قال فبعزتك لأغوينهم أجمعين»؛ فأقسم بعزّةِ الله على إغواءِ بني آدمَ كلِّهم؛ ففي هذا بيانُ شدّةِ عداوةِ إبليسَ لبني آدمَ وحرصِه على إغوائهم وإضلالهم؛ فاحذر عدوّك إبليسَ الذي أقسم على إغوائك وإضلالك؛ فاتّخذه عدوًّا كما هو لك عدوٌّ مبين؛ إنّ الشيطانَ لكم عدوٌّ فاتّخذوه عدوًّا؛ فلا تغفل عن عداوته وكيده وحبائله؛ فإنه يراك من حيث لا تراه، ويأتيك من كلِّ جهة؛ فاستعذ بالله من الشيطانِ الرجيم؛ وحصّن نفسك بالأذكارِ والطاعات؛ فالغفلةُ عن عداوةِ الشيطانِ سببُ الوقوعِ في حبائله ومكايده؛ فكن على حذرٍ دائمٍ منه؛ وإذا نزغك منه نزغٌ فاستعذ بالله؛ فمن استعاذ بالله بصدقٍ أعاذه؛ فجاهد عدوّك الشيطانَ بطاعةِ الله ومخالفةِ هواه؛ فإنّ كيدَ الشيطانِ كان ضعيفًا أمام من اعتصم بالله؛ فاعتصم بالله من عدوّك، ولا تتّبع خطواته."}},{"n":83,"reflection":{"text":"«إلا عبادك منهم المخلصين» — إلا عبادَك المخلصين منهم، فلا سبيلَ لي عليهم؛ ففي هذا أنّ الإخلاصَ عصمةٌ من كيدِ الشيطان؛ فأخلص عبادتك لله لتكون من المخلصين الذين لا سلطانَ للشيطانِ عليهم، فالإخلاصُ حصنٌ من إغواءِ الشيطان، فحقّق الإخلاصَ لتنجو من كيده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الإخلاصِ حصنًا من كيدِ الشيطانِ وإغوائه."},"action":{"text":"تأمّل اعترافَ إبليسَ بعجزه عن المخلصين: قال لأغوينّهم أجمعين إلا عبادك المخلصين منهم، فإني لا أقدر على إغوائهم ولا سبيلَ لي عليهم «إلا عبادك منهم المخلصين»؛ ففي هذا أنّ الإخلاصَ لله عصمةٌ وحصنٌ من كيدِ الشيطانِ وإغوائه؛ فالمخلصون الذين أخلصوا دينهم وعبادتهم لله لا يقدر الشيطانُ على إضلالهم؛ إنّ عبادي ليس لك عليهم سلطان؛ فأخلص عبادتك لله وحده لتكون من المخلصين الذين لا سلطانَ للشيطانِ عليهم؛ فالإخلاصُ حصنٌ حصينٌ من إغواءِ الشيطانِ وكيده؛ فحقّق الإخلاصَ في عبادتك ونيّتك وعملك؛ واجعل أعمالك كلَّها خالصةً لوجهِ الله؛ فمن أخلص لله عصمه من الشيطان؛ فالشيطانُ إنما يتسلّط على من ضعف إخلاصه وتعلّق قلبه بغيرِ الله؛ فطهّر نيّتك من الرياءِ والسمعةِ وحظوظِ النفس؛ وأخلص قلبك لله في محبّته وخوفه ورجائه وعبادته؛ فبالإخلاصِ تنجو من كيدِ الشيطانِ وحبائله؛ فاجعل الإخلاصَ حصنك، والإخلاصَ سلاحك؛ فمن أخلص لله نجا من الشيطان، ومن لم يخلص تسلّط عليه؛ فحقّق الإخلاص، تعتصم من إغواءِ عدوّك."}},{"n":84,"reflection":{"text":"«قال فالحق والحق أقول» — قال الله: فالحقُّ منّي، والحقَّ أقول (قسمٌ وتأكيد)؛ ففي هذا تأكيدُ الله لوعيدِه بالحقّ؛ فاعلم أنّ قولَ الله حقٌّ ووعيدَه حقٌّ نافذ، فخذ وعيدَ الله مأخذَ الجدّ، فما قاله الله واقعٌ لا محالة، فاستعدّ لما أخبر به من الجزاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ قولَ الله ووعيدَه حقٌّ نافذ، والاستعدادُ له."},"action":{"text":"تأمّل تأكيدَ الله لوعيده: قال فالحقُّ منّي، والحقَّ أقول، لا أقول إلا حقًّا؛ فهذا قسمٌ وتوكيدٌ من الله بأنّ ما سيقوله حقٌّ واقعٌ لا محالة «قال فالحق والحق أقول»؛ ففي هذا تأكيدُ الله لوعيده بالحقّ؛ فاعلم أنّ قولَ الله كلَّه حق، ووعده حق، ووعيده حقٌّ نافذٌ لا يتخلّف؛ فالله لا يقول إلا الحق، ولا يعد ولا يوعد إلا بالحق؛ فخذ وعيدَ الله مأخذَ الجدِّ والحذر؛ فما أخبر الله بوقوعه فهو واقعٌ لا محالة؛ ومن أصدقُ من الله قيلًا؟ ومن أصدقُ من الله حديثًا؟ فاستعدّ لما أخبر الله به من الجزاءِ والحسابِ والجنّةِ والنار؛ ولا تشكّ في شيءٍ من وعدِ الله ووعيده؛ فكلُّه حقٌّ سيقع؛ فمن أيقن بأنّ قولَ الله حقٌّ استعدّ للقائه وعمل لآخرته؛ فاجعل يقينك بصدقِ وعدِ الله ووعيده حافزًا للعملِ والاستعداد؛ فالله أصدقُ القائلين، وأحكمُ الحاكمين؛ فما قاله فهو الحقُّ الذي لا مريةَ فيه؛ فآمن بوعدِ الله ووعيده، واستعدّ لما أخبر به؛ فإنه الحقُّ الواقعُ لا محالة."}},{"n":85,"reflection":{"text":"«لأملأن جهنم منك وممن تبعك منهم أجمعين» — لأملأنّ جهنمَ منك يا إبليسُ ومن تبعك من بني آدمَ أجمعين؛ ففي هذا وعيدُ الله لإبليسَ وأتباعه بالنار؛ فاحذر أن تكون من أتباعِ الشيطانِ فتملأ بهم جهنم، فمن اتّبع الشيطانَ فمصيره النارُ معه، فخالف الشيطانَ واتّبع الحقَّ لتنجو من النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّباعِ الشيطان، فمصيرُ أتباعِه النارُ معه."},"action":{"text":"تأمّل وعيدَ الله لإبليسَ وأتباعه: لأملأنّ جهنمَ منك يا إبليسُ ومن تبعك من بني آدمَ في الكفرِ والمعاصي أجمعين «لأملأن جهنم منك وممن تبعك منهم أجمعين»؛ ففي هذا وعيدُ الله لإبليسَ وأتباعه بأن يملأ بهم جهنم؛ فاحذر أن تكون من أتباعِ الشيطانِ فتُحشَر معه في النار؛ فمن اتّبع الشيطانَ وأطاعه في الكفرِ والمعاصي فمصيره النارُ معه؛ فالشيطانُ يقود أتباعه إلى النار؛ إنما يدعو حزبه ليكونوا من أصحابِ السعير؛ فخالف الشيطانَ ولا تتّبع خطواته؛ واتّبع الحقَّ والهدى الذي جاءت به الرسل؛ فمن خالف الشيطانَ واتّبع الحقَّ نجا من النار، ومن اتّبع الشيطانَ وأطاعه هلك معه فيها؛ فلا تجعل الشيطانَ قائدك وإمامك؛ بل اجعل الله ورسوله قائدك وإمامك؛ فراقب نفسك: أتتبع الشيطانَ أم تخالفه؟ فكلّما دعاك إلى معصيةٍ فخالفه؛ وكلّما ثبّطك عن طاعةٍ فاعصه؛ فبمخالفةِ الشيطانِ تنجو من النار؛ فاجعل مخالفةَ الشيطانِ دأبك، واتّباعَ الحقِّ سبيلك؛ فتنجو من أن تكون ممّن تُملأ بهم جهنم."}}]},{"title":"ختامُ السورة: لا أجرَ على البلاغ، والقرآنُ ذكرٌ للعالمين","range":[86,88],"theme":"أمرُ النبيِّ أن يعلن أنه لا يسأل على الدعوةِ أجرًا وليس من المتكلّفين، وأنّ القرآنَ ما هو إلا ذكرٌ للعالمين، وأنّ المكذّبين سيعلمون صدقَ نبئه بعد حين","verses":[{"n":86,"reflection":{"text":"«قل ما أسألكم عليه من أجر وما أنا من المتكلفين» — قل يا محمدُ: ما أطلب منكم على تبليغِ الرسالةِ أجرًا، ولست ممّن يتكلّف ما لم يُؤمَر به أو يدّعي ما ليس له؛ ففي هذا نزاهةُ الداعيةِ عن طلبِ الأجرِ وتركُ التكلّف؛ فاجعل دعوتك ونصحك خالصًا لله بلا مقابل، ودع التكلّفَ والتصنّع، فالإخلاصُ في الدعوةِ وتركُ التكلّفِ من صفاتِ الصادقين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعوةِ بلا مقابل، وتركُ التكلّفِ والتصنّع."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله: ما أطلب منكم على تبليغِ هذا القرآنِ والدعوةِ إليه أجرًا ولا مالًا ولا جزاءً منكم، ولست ممّن يتكلّف ويتصنّع ما لم يُؤمَر به، أو يدّعي ما ليس عنده «قل ما أسألكم عليه من أجر وما أنا من المتكلفين»؛ ففي هذا نزاهةُ الداعيةِ عن طلبِ الأجرِ على دعوته، وتركُ التكلّفِ والتصنّع؛ فاجعل دعوتك إلى الله ونصحك للناسِ خالصًا لله، لا تطلب عليه أجرًا ولا جزاءً ولا شكرًا من الناس؛ إنما نطعمكم لوجهِ الله لا نريد منكم جزاءً ولا شكورًا؛ فالإخلاصُ في الدعوةِ والنصحِ من صفاتِ المرسلين وأتباعهم؛ ودع التكلّفَ والتصنّعَ وادّعاءَ ما ليس عندك؛ فلا تتكلّف علمًا لا تعلمه، ولا حالًا لا تملكه، ولا تتقوّل على الله بلا علم؛ فالصادقُ لا يتكلّف؛ فاجعل دعوتك وعبادتك وعملك خالصةً لله، خاليةً من التكلّفِ والرياءِ والتصنّع؛ فمن أخلص لله في دعوته وترك التكلّفَ نفع الله به؛ فالإخلاصُ وتركُ التكلّفِ من علاماتِ الصدقِ والقبول؛ فاقتدِ بالنبيِّ ﷺ في إخلاصِ الدعوةِ وتركِ التكلّف."}},{"n":87,"reflection":{"text":"«إن هو إلا ذكر للعالمين» — ما هذا القرآنُ إلا ذكرٌ وموعظةٌ وشرفٌ لجميعِ العالمين؛ ففي هذا عمومُ نفعِ القرآنِ للناسِ كافّة؛ فاعلم أنّ القرآنَ ذكرٌ للعالمين، فتذكّر به واتّعظ، وبلّغه للناسِ ليتذكّروا، فالقرآنُ رحمةٌ وذكرى للعالمين، فانتفع به وانفع به غيرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بالقرآنِ وتبليغُه، فهو ذكرٌ للعالمين."},"action":{"text":"تأمّل ختامَ السورةِ ببيانِ عمومِ نفعِ القرآن: ما هذا القرآنُ إلا ذكرٌ وموعظةٌ وشرفٌ وتذكيرٌ لجميعِ العالمين من الإنسِ والجنّ «إن هو إلا ذكر للعالمين»؛ ففي هذا بيانُ أنّ القرآنَ ذكرٌ ونفعٌ عامٌّ للناسِ كافّة، لا يختصّ بقومٍ دون قوم؛ فاعلم أنّ القرآنَ ذكرٌ للعالمين، أنزله الله رحمةً وهدايةً وموعظةً للجميع؛ فتذكّر به واتّعظ بمواعظه، وانتفع بهداياته؛ وبلّغه للناسِ ليتذكّروا وينتفعوا؛ فالقرآنُ رحمةٌ وذكرى وشفاءٌ وهدًى للعالمين؛ فانتفع به أنت أولًا بالتلاوةِ والتدبّرِ والعمل؛ ثم انفع به غيرك بالتبليغِ والدعوةِ والتعليم؛ بلّغوا عني ولو آية؛ فخيركم من تعلّم القرآنَ وعلّمه؛ فاجعل القرآنَ ذكرك وموعظتك وشرفك؛ وكن من حملته العاملين به، الداعين إليه؛ فمن انتفع بالقرآنِ ونفع به غيره فقد فاز بخيرٍ عظيم؛ فالقرآنُ ذكرٌ للعالمين، فكن ممّن يتذكّر به ويذكّر؛ فبالقرآنِ تُنال السعادةُ في الدنيا والآخرة."}},{"n":88,"reflection":{"text":"«ولتعلمن نبأه بعد حين» — ولتعلمنّ أيها المكذّبون خبرَ صدقِ القرآنِ وما فيه من الوعدِ والوعيدِ بعد حين (عند الموتِ أو يومَ القيامة)؛ ففي هذا وعيدُ المكذّبين بأنهم سيعلمون الحقيقة؛ فاعلم أنّ صدقَ القرآنِ سيظهر لكلِّ أحد، فبادر بالإيمانِ والعملِ قبل أن تعلم الحقيقةَ حين لا ينفع العلم، فالسعيدُ من علم صدقه فآمن قبل فواتِ الأوان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ قبل انكشافِ الحقيقةِ حين لا ينفع."},"action":{"text":"تأمّل ختامَ السورةِ بوعيدِ المكذّبين: ولتعلمنّ أيها المكذّبون خبرَ هذا القرآنِ وصدقَ ما فيه من الوعدِ والوعيدِ والبعثِ والجزاءِ بعد حين — عند الموتِ أو يومَ القيامة «ولتعلمن نبأه بعد حين»؛ ففي هذا وعيدٌ للمكذّبين بأنهم سيعلمون صدقَ القرآنِ يقينًا حين لا ينفعهم العلم؛ فاعلم أنّ صدقَ القرآنِ وحقيقةَ ما فيه سيظهران لكلِّ أحدٍ لا محالة؛ فمن آمن به في الدنيا علم صدقه فنجا، ومن كذّب به علم صدقه في الآخرةِ حين لا ينفع العلمُ ولا الندم؛ فبادر أنت بالإيمانِ بالقرآنِ والعملِ بما فيه قبل أن تنكشف الحقيقةُ حين لا ينفع الإيمان؛ فالسعيدُ من علم صدقَ القرآنِ فآمن به وعمل قبل فواتِ الأوان؛ والشقيُّ من كذّب به حتى عاين الحقيقةَ فندم حيث لا ينفع الندم؛ فلا تؤخّر الإيمانَ والعملَ حتى تعلم الحقيقةَ رغمًا عنك؛ بل بادر بالإيمانِ والتصديقِ والعملِ الآن؛ فمن آمن قبل المعاينةِ نفعه إيمانه، ومن أخّره حتى المعاينةِ لم ينفعه؛ فآمن بالقرآنِ، واعمل بما فيه، واستعدّ ليومٍ تعلم فيه نبأه؛ فبادر قبل أن يأتيَ الحينُ الذي تعلم فيه الحقيقةَ ولا ينفعك."}}]}],"coverage":{"covered":88,"total":88}};
